    "faq.title": "Frequently asked questions",
    "faq.q1": "Can I really not unlock early?",
    "faq.a1": "That's the core idea. Once a scheduled program starts, it runs until its end time. If you could switch it off in two taps, it would be a reminder, not a lock. Set your durations thoughtfully.",
    "faq.q2": "Where does my data go?",
    "faq.a2": "Nowhere. Pawlock has no account system and no servers. Your usage data is processed on your device by the system itself, and we never see it.",
    "faq.q3": "Why does it ask for Screen Time permission?",
    "faq.a3": "Locking apps is only possible through the system's own controls: Apple's Screen Time (Family Controls) on iPhone, and the accessibility service on Android. The permission is granted to your phone's system and is required for any real blocking to work.",
    "faq.q4": "What do I get for free?",
    "faq.a4": "3 instant locks per day, 1 automatic program, app and website blocking, and daily Screen Time statistics. Pro unlocks unlimited programs and all current Pro features.",
    "faq.q5": "How do I cancel my subscription?",
    "faq.a5": "Through your App Store or Google Play subscriptions, like any other subscription. If you cancel, Pro stays active until the end of the paid period.",
