    "why.legendNo": "Rarement",

    "reviews.title": "Ce qu'en disent les gens",
    "reviews.sub": "Des histoires vraies de la lutte contre le scroll.",
    "reviews.r1t": "je scrollais jusqu'à 2h du matin tous les soirs. horaire sommeil qui verrouille tout à 23h, la première semaine a été dure mais maintenant je dors vraiment 7h",
    "reviews.r1n": "camille.prt",
    "reviews.r2t": "en période de partiels je ne lâchais pas mon téléphone. verrouillé de 9h à 18h en semaine, panique le premier jour, habituée le troisième. mes notes ont suivi",
    "reviews.r2n": "manon.etudie",
    "reviews.r3t": "je suis le genre à ouvrir instagram au boulot et perdre 40 minutes. l'horaire travail tourne maintenant, téléphone mort jusqu'à midi. c'est moi qui l'ai voulu hein, pas mon patron",
    "reviews.r3n": "theo_dev",
    "reviews.r4t": "je me suis surpris à regarder mon téléphone en jouant avec mon fils, ça m'a fait mal. verrouillage famille de 18h à 21h. ma fille remarque que papa ne regarde plus l'écran",
    "reviews.r4n": "nico_papa",
    "reviews.r5t": "j'ai supprimé instagram 100 fois et toujours réinstallé. supprimer ne sert à rien, verrouiller oui. 3 semaines sans y entrer et l'envie diminue",
    "reviews.r5n": "lea.mrt",
    "reviews.r6t": "la première heure de ma journée partait dans le téléphone avant même de me lever. verrouillage matin 7h 9h, je bois mon café et je marche. cette heure est de nouveau à moi",
    "reviews.r6n": "chloe_run",
    "reviews.r7t": "je n'arrivais plus à lire, deux pages et la main allait au téléphone. avec le verrouillage lecture du soir j'ai fini 3 livres ce mois-ci. la dernière fois c'était à la fac",
    "reviews.r7n": "hugo.lit",
    "reviews.r8t": "les autres bloqueurs je les contournais en 2 gestes, je me mentais à moi-même. celui-là on ne peut pas l'éteindre et oui ça agace au début mais c'est le seul truc qui ait jamais marché",
    "reviews.r8n": "louis_lyn",
    "reviews.r9t": "les stats m'ont choqué, 6h40 par jour. en 2 mois je suis à 3h. voir la courbe descendre c'est bizarrement ce qui motive le plus",
    "reviews.r9n": "emma.rvl",
    "reviews.r10t": "impossible de sortir du trou noir des shorts alors j'ai verrouillé youtube, problème réglé. avec un widget ce serait 5 étoiles, sinon rien à redire",
    "reviews.r10n": "nathan_035",
    "reviews.note": "Exemples illustratifs. Cette section sera mise à jour avec de vrais avis des stores après le lancement.",

    "faq.title": "Questions fréquentes",
    "faq.q1": "Je ne peux vraiment pas déverrouiller avant la fin ?",
    "faq.a1": "C'est l'idée centrale. Une fois lancé, un horaire programmé court jusqu'à son heure de fin. Si tu pouvais le couper en deux gestes, ce serait un rappel, pas un verrou. Choisis tes durées avec soin.",
    "faq.q2": "Où vont mes données ?",
    "faq.a2": "Nulle part. Pawlock n'a ni compte ni serveur. Tes données d'usage sont traitées sur ton appareil par le système lui-même, et nous ne les voyons jamais.",
    "faq.q3": "Pourquoi l'app demande-t-elle l'autorisation Temps d'écran ?",
    "faq.a3": "Verrouiller des apps n'est possible qu'via les contrôles du système : Temps d'écran (Contrôles parentaux) d'Apple sur iPhone, et le service d'accessibilité sur Android. L'autorisation est accordée au système de ton téléphone et elle est indispensable pour un vrai blocage.",
    "faq.q4": "Qu'est-ce qui est gratuit ?",
    "faq.a4": "3 verrouillages instantanés par jour, 1 horaire automatique, blocage d'apps et de sites web, et Statistiques quotidiennes de Temps d'écran. Pro débloque les horaires illimités et toutes les fonctions Pro actuelles.",
    "faq.q5": "Comment résilier l'abonnement ?",
    "faq.a5": "Depuis tes abonnements App Store ou Google Play, comme n'importe quel abonnement. Si tu annules, Pro reste actif jusqu'à la fin de la période payée.",
    "faq.q6": "Quels appareils sont compatibles ?",
    "faq.a6": "Pawlock fonctionne sur iPhone et sur Android. Consulte la fiche du store pour les versions requises.",

    "cta.title": "Reprends ton temps.",
    "cta.sub": "Ton feed peut attendre. Pas ta vie.",
