    "how.s2t": "Bloqueie agora ou agende",
    "how.s2d": "Um toque para um bloqueio instantâneo com timer, ou crie horários automáticos: sono, estudo, trabalho. Com suporte a períodos que viram a noite.",
    "how.s3t": "Sem volta. Esse é o ponto.",
    "how.s3d": "Quando um horário começa, não dá para encerrar antes. O Pawlock fica de guarda enquanto você vive a sua vida.",

    "features.title": "Tudo o que você precisa para recuperar seu tempo",
    "features.sub": "Um bloqueio sério por baixo, um rosto amigável por cima.",
    "features.f1t": "Bloqueio instantâneo",
