    "features.f3t": "Rígido de propósito",
    "features.f3d": "Um horário iniciado não pode ser desligado antes. O bloqueio que não se deixa convencer é o que muda seus hábitos.",
    "features.f4t": "Estatísticas de verdade",
    "features.f4d": "Uso diário, semanal e mensal lido do próprio telefone. Números reais do seu aparelho, não estimativas.",
