    "reviews.title": "O que estão dizendo",
    "reviews.sub": "Histórias reais da luta contra o scroll.",
    "reviews.r1t": "eu ficava rolando até as 2 da manhã todo dia. horário de sono bloqueia tudo às 23h, a primeira semana foi difícil mas agora durmo 7 horas de verdade",
    "reviews.r1n": "carol.rj",
    "reviews.r2t": "época de prova me salvou. bloqueio de 9 às 18 nos dias úteis, dia um entrei em pânico, dia três já tinha acostumado. minhas notas sentiram a diferença",
    "reviews.r2n": "ju.estuda",
    "reviews.r3t": "sou o cara que abre o instagram no trabalho e perde 40 minutos. horário de trabalho rodando, celular morto até o almoço. fui eu que quis, não meu chefe",
    "reviews.r3n": "joao.dev",
    "reviews.r4t": "me peguei olhando o celular brincando com meu filho e me senti péssimo. bloqueio família das 18 às 21. minha filha já percebe que o pai não olha mais a tela",
    "reviews.r4n": "rafa_pai",
    "reviews.r5t": "apaguei o instagram umas 100 vezes e sempre reinstalava. apagar não resolve, bloquear resolve. 3 semanas sem entrar e a vontade tá diminuindo",
    "reviews.r5n": "ana.clr",
    "reviews.r6t": "a primeira hora do dia ia embora no celular antes de eu levantar. bloqueio da manhã 7 às 9, tomo meu café e vou caminhar. essa hora voltou a ser minha",
    "reviews.r6n": "bia_corre",
    "reviews.r7t": "eu não conseguia mais ler livro, duas páginas e a mão ia pro celular. com o bloqueio de leitura à noite terminei 3 livros esse mês. a última vez foi na faculdade",
    "reviews.r7n": "pedro.le",
    "reviews.r8t": "outros bloqueadores eu burlava em 2 toques, tava me enganando. esse não tem como desligar e sim, no começo irrita, mas é a única coisa que funcionou",
    "reviews.r8n": "lucas_sp",
    "reviews.r9t": "as estatísticas me assustaram, 6h40 por dia. em 2 meses caí pra 3 horas. ver o gráfico descendo é o que mais motiva",
    "reviews.r9n": "duda.mrs",
    "reviews.r10t": "não saía do buraco negro dos shorts então bloqueei o youtube, resolvido. com widget seriam 5 estrelas, fora isso zero reclamação",
    "reviews.r10n": "gabriel_035",
    "reviews.note": "Exemplos ilustrativos. Esta seção será atualizada com avaliações reais das lojas após o lançamento.",

    "faq.title": "Perguntas frequentes",
    "faq.q1": "Eu realmente não consigo desbloquear antes?",
    "faq.a1": "Essa é a ideia central. Quando um horário agendado começa, ele roda até o fim. Se desse para desligar em dois toques, seria um lembrete, não um bloqueio. Defina as durações com cuidado.",
    "faq.q2": "Para onde vão meus dados?",
    "faq.a2": "Para lugar nenhum. O Pawlock não tem contas nem servidores. Seus dados de uso são processados no aparelho, pelo próprio sistema, e nunca os vemos.",
    "faq.q3": "Por que ele pede permissão de Tempo de Uso?",
    "faq.a3": "Bloquear apps só é possível pelos controles do sistema: Tempo de Uso (Controles Familiares) da Apple no iPhone e o serviço de acessibilidade no Android. A permissão é concedida ao sistema do seu telefone e é obrigatória para um bloqueio real.",
    "faq.q4": "O que vem de graça?",
    "faq.a4": "3 bloqueios instantâneos por dia, 1 horário automático, bloqueio de apps e sites, e Estatísticas diárias de Tempo de Uso. O Pro libera horários ilimitados e todos os recursos Pro atuais.",
    "faq.q5": "Como cancelo a assinatura?",
    "faq.a5": "Pelas assinaturas da App Store ou do Google Play, como qualquer outra. Se cancelar, o Pro continua ativo até o fim do período pago.",
    "faq.q6": "Quais aparelhos são compatíveis?",
    "faq.a6": "O Pawlock funciona no iPhone e no Android. Confira a página da loja para os requisitos de versão atuais.",

