    "problem.sub": "あなたの時間を奪うアプリは、たった一つの目的のために何千人ものエンジニアがつくったもの。それは、あなたにスクロールを続けさせること。意志の力では、はじめから勝ち目のない戦いでした。",
    "problem.c1t": "「ほんの5分だけ」",
    "problem.c1d": "ちょっとだけ開いたはず。気づけば1時間後もまだそこにいて、何を見ていたかさえ覚えていない。",
    "problem.c2t": "削除しても意味がない",
    "problem.c2d": "固い決意でアプリを削除する。2日後には、またホーム画面に戻っている。",
    "problem.c3t": "リマインダーは無視できる",
    "problem.c3d": "スクリーンタイムの警告も「休憩しましょう」のポップアップも、ワンタップで消えてしまう。必要なのは提案ではなく、ロックです。",
    "problem.stat1n": "4時間以上",
    "problem.stat1d": "平均的な人が毎日スマホに費やしている時間です",
    "problem.stat2n": "91日",
    "problem.stat2d": "このペースだと、起きている1年のうちこれだけの日々が画面に消えていきます",
    "problem.stat3n": "4分の1",
    "problem.stat3d": "起きている16時間のうち、4時間に1時間がスマホに使われています",
    "problem.note": "計算はシンプルです。1日4時間 × 365日 = 年に1,460時間。1日を起きている16時間として数えると（残りの8時間は睡眠）、まるまる91日分の起床時間になります。Pawlockの統計は、あなた自身の数字を端末から直接お見せします。",
    "transition.title": "その向こう側で、あなたの人生が待っています。",
    "transition.sub": "スマホを置いても、失うものは何もありません。取り戻せるのは、まるまる一日分の時間です。",
    "how.title": "Pawlockの仕組み",
    "how.sub": "3つのステップ。あとは、やる気が続かない日でも仕組みが働き続けます。",
    "how.s1t": "気を散らすものを選ぶ",
    "how.s1d": "Apple公式のピッカーで、アプリやカテゴリ全体、ウェブサイトを選択。アドレスを入力すれば、どんなサイトでも追加できます。",
    "how.s2t": "今すぐ、または予約してロック",
    "how.s2d": "ワンタップでタイマー付きの即時ロック。または睡眠、勉強、仕事など自動プログラムを作成。日をまたぐ時間帯にも対応しています。",
