    "hero.badge": "iPhone 与 Android 的应用锁与屏幕时间守卫",
    "hero.title1": "更少屏幕，",
    "hero.title2": "更多",
    "hero.title3": "生活。",
    "hero.sub": "Pawlock 替你锁定那些让你分心的应用和网站。别再靠意志力硬撑，建立一套真正管用的系统。",
    "hero.cta": "免费下载",
    "hero.cta2": "看看它如何运作",
    "hero.trust1": "你的数据绝不离开设备",
    "hero.trust2": "无需注册账户",
    "hero.trust3": "基于手机自带的系统控制",
    "hero.trust4": "无广告",
    "problem.title": "不是你的错，是设计使然。",
    "problem.sub": "那些偷走你时间的应用，是成千上万工程师为一个目标打造的：让你不停地刷。意志力从来不是一场公平的较量。",
    "problem.c1t": "“就看五分钟”",
    "problem.c1d": "你只想看一会儿。一个小时过去了，你还在刷，甚至想不起自己看了什么。",
    "problem.c2t": "删掉根本没用",
    "problem.c2d": "你满怀决心删掉了应用。两天后，它又回到了你的主屏幕上。",
    "problem.c3t": "提醒可以随手忽略",
    "problem.c3d": "屏幕时间警告和“休息一下”的弹窗，一点就消失了。你需要的是一把锁，而不是一句建议。",
    "problem.stat1n": "4+ 小时",
    "problem.stat1d": "是普通人每一天花在手机上的时间",
    "problem.stat2n": "91 天",
    "problem.stat2d": "照这个节奏，你一年清醒的日子就这样消失在屏幕里",
    "problem.stat3n": "四分之一",
    "problem.stat3d": "的清醒时间给了手机，以每天 16 小时清醒来算",
    "problem.note": "算法很简单：4 小时 × 365 天 = 一年 1460 小时。把一天算作 16 个清醒小时（另外 8 小时用来睡觉），那就是整整 91 个清醒的日子。Pawlock 的统计会直接从你的设备上显示属于你自己的那个数字。",
    "transition.title": "而在另一头，你的生活正在等你。",
    "transition.sub": "放下手机你什么都不会失去，反而会赚回一整天。",
    "how.title": "Pawlock 如何运作",
    "how.sub": "三步搞定。之后即使动力全无，系统依然照常运转。",
    "how.s1t": "选出让你分心的东西",
    "how.s1d": "用 Apple 官方的选择器挑出应用、整个分类或网站。输入网址还能添加任意站点。",
    "how.s2t": "立即锁定，或按时间表锁定",
    "how.s2d": "一点即可开启带计时器的即时锁定，或创建自动程序：睡眠、学习、工作。也支持跨夜时段。",
    "how.s3t": "没有回头路，这正是关键。",
    "how.s3d": "程序一旦开始，就无法提前结束。Pawlock 替你站岗，让你安心去过自己的生活。",
    "features.title": "夺回时间所需的一切，都在这里",
    "features.sub": "底层是硬核的拦截，表面是友好的模样。",
    "features.f1t": "即时锁定",
    "features.f1d": "一点即可锁定你选中的应用和网站。拨动滚轮设置天、时、分，看着专注倒计时开始。",
    "features.f2t": "个性化程序建议",
    "features.f2d": "回答几个新手引导问题，Pawlock 就会根据你的习惯、目标和日常作息自动生成程序建议。",
    "features.f3t": "严格是设计使然",
    "features.f3d": "已经开始的程序无法提前关闭。那把无法被说服放弃职守的锁，才是能改变你习惯的锁。",
    "features.f4t": "真实统计",
    "features.f4d": "基于 Apple 屏幕使用时间数据的每日、每周和每月使用情况。数据直接来自你的设备，并非估算。",
    "features.f5t": "网站也能锁",
    "features.f5d": "分心的不只是应用。可以把网站和整类站点与应用一起，放进同一把锁里。",
    "features.f6t": "默认保护隐私",
    "features.f6d": "无账户、无服务器、无广告。你的屏幕使用时间数据留在你的 iPhone 上，正如 Apple 一贯的做法。",
    "features.f7t": "实时倒计时",
    "features.f7d": "通过锁定屏幕上带吉祥物的实时活动和灵动岛中的紧凑倒计时，随时查看锁定进度。",
    "features.f8t": "智能每日通知",
    "features.f8d": "根据你的连续记录、被拦截的打开尝试或每周专注摘要，每天收到实用提醒。",
    "spot.auto.badge": "自动",
    "spot.auto.title": "哪怕你在睡觉，它也在站岗。",
    "spot.auto.sub": "把程序设置一次，剩下的交给 Pawlock。每个夜晚和每个清晨，它都会准时锁定。你甚至不用去记。",
    "spot.auto.b1": "跨夜时段，例如 晚 11 点 → 早 7 点",
    "spot.auto.b2": "每个程序开始时都有通知",
    "spot.auto.b3": "每天、工作日或周末，一点搞定",
    "spot.strict.badge": "不可破解",
    "spot.strict.title": "一把你怎么说都解不开的锁。",
    "spot.strict.sub": "大多数拦截器在你真想进去的那一刻就妥协了。Pawlock 不会。程序一旦开始，就没有提前退出，也没有两下点击的逃生门。这正是它能改变你习惯的全部理由。",
    "spot.strict.b1": "已开始的程序无法提前结束",
    "spot.strict.b2": "基于 Apple 系统级的屏幕使用时间打造",
    "spot.strict.b3": "没有漏洞，没有“就这一次”",
    "effect.title": "看见你夺回的时间",
    "effect.sub": "Pawlock 让你看到前后对比：你的使用如何变化、你最忙的时段，以及你想打开被锁应用的时刻。看着夺回的时间一点点增长，是最好的动力。",
    "effect.b1": "前后对比",
    "effect.b2": "你最忙的使用时段",
    "effect.b3": "夺回的时间，一天天累积",
    "effect.b4": "每天少用 1 小时：每年多赚 23 个清醒的日子",
    "pricing.title": "免费版与 Pro",
    "pricing.sub": "免费开始。当你的习惯需要更多时，再升级。",
    "pricing.freeName": "免费版",
    "pricing.freePrice": "永久免费",
