    "reviews.title": "大家怎么说",
    "reviews.sub": "来自对抗刷屏之战的真实故事。",
    "reviews.r1t": "以前每天都刷到凌晨两点。设了个睡眠时间表，晚上 11 点全部锁死，第一周真的难熬，但现在我居然能睡够 7 小时了",
    "reviews.r1n": "陈子豪",
    "reviews.r2t": "期末周救了我。工作日把手机从早 9 点锁到晚 6 点，第一天慌得不行，第三天就习惯了。刷题正确率明显上去了",
    "reviews.r2n": "李思悦",
    "reviews.r3t": "我就是那种上班一开 Instagram 就没了 40 分钟的人。现在工作时间表锁一整个上午，手机基本上午都是死的。顺便说一句没人逼我，是我自己设的",
    "reviews.r3n": "王浩然",
    "reviews.r4t": "有次陪孩子玩还在看手机，心里特别难受。现在设了晚上 6 到 9 点的家庭锁定，我女儿真的发现爸爸不再盯着手机了",
    "reviews.r4n": "张伟",
    "reviews.r5t": "Instagram 我大概删了一百次又装回来。原来删不是答案，锁才是。已经戒了 3 周，说真的那股冲动在慢慢消退",
    "reviews.r5n": "刘婧",
    "reviews.r6t": "以前每天第一个小时还没下床就消失在手机里了。现在早上 7 到 9 点锁定，我喝着咖啡出门散步。把那个小时重新抓回手里，完全是另一种人生",
    "reviews.r6n": "赵敏",
    "reviews.r7t": "以前根本读不下去书，翻两页手就去摸手机。设了晚间阅读锁定后，这个月读完了 3 本书。上次这样还是大学的时候",
    "reviews.r7n": "孙一鸣",
    "reviews.r8t": "别的拦截器我两下就能绕过去，基本是在骗自己。这个你根本关不掉，刚开始确实烦人，但它是唯一真正管用的",
    "reviews.r8n": "周凯",
    "reviews.r9t": "统计数据把我吓到了，一天 6 小时 40 分钟。两个月降到了 3 小时。看着那条曲线往下走，居然是最有动力的部分",
    "reviews.r9n": "林雨桐",
    "reviews.r10t": "刷短视频掉进黑洞出不来，干脆把 YouTube 锁了，问题解决。要是有个小组件就是五星了，其他没啥可挑的",
    "reviews.r10n": "吴天磊",
    "reviews.note": "示例内容。本版块将在上线后更新为真实的 App Store 评价。",
    "faq.title": "常见问题",
    "faq.q1": "我真的没法提前解锁吗？",
    "faq.a1": "这正是核心理念。已安排的程序一旦开始，就会一直运行到结束时间。如果你两下点击就能关掉它，那它就成了提醒，而不是锁。请慎重设置你的时长。",
    "faq.q2": "我的数据会去哪里？",
    "faq.a2": "哪儿都不去。Pawlock 没有账户系统，也没有服务器。你的屏幕使用时间数据通过 Apple 的框架在你的设备上处理，我们从来看不到。",
    "faq.q3": "为什么要申请屏幕使用时间权限？",
    "faq.a3": "锁定应用只能通过系统自身的控制实现：iPhone 上是 Apple 的屏幕使用时间（家人共享），Android 上是无障碍服务。权限授予手机系统，是真正屏蔽的前提。",
    "faq.q4": "免费版能得到什么？",
    "faq.a4": "每天 3 次即时锁定、1 个自动程序、应用和网站拦截，以及每日屏幕使用时间统计。Pro 解锁无限自动程序，并包含所有当前 Pro 功能。",
    "faq.q5": "如何取消订阅？",
    "faq.a5": "在 App Store 或 Google Play 的订阅中管理，和其他订阅一样。取消后 Pro 会保留到已付费周期结束。",
    "faq.q6": "支持哪些设备？",
    "faq.a6": "Pawlock 支持 iPhone 和 Android。当前版本要求请查看商店页面。",
