    "pricing.proNote": "Settimanale, mensile o annuale. I prezzi sono mostrati nell'App Store per la tua regione.",
    "why.title": "Perché Pawlock?",
    "why.sub": "Un confronto onesto con le tipiche app blocker.",
    "why.colOthers": "Blocker tipici",
    "why.r1": "Blocco a livello di sistema tramite la tecnologia ufficiale Tempo di utilizzo di Apple",
    "why.r2": "I blocchi non possono essere terminati prima",
    "why.r3": "Programmi automatici con finestre notturne",
