    "why.legendSome": "Alcuni sì",
    "why.legendNo": "Di solito no",
    "reviews.title": "Cosa dicono le persone",
    "reviews.sub": "Storie vere dalla lotta contro lo scroll.",
    "reviews.r1t": "andavo avanti a scorrere fino alle 2 di notte tutte le sere. ho impostato un programma sonno che blocca tutto alle 23 e la prima settimana è stata dura ma adesso dormo davvero 7 ore",
    "reviews.r1n": "luca_mrc",
    "reviews.r2t": "la settimana degli esami mi ha salvato. telefono bloccato dalle 9 alle 18 nei feriali, il primo giorno panico totale, al terzo ci avevo fatto l'abitudine. i miei voti alle simulazioni sono schizzati su",
    "reviews.r2n": "giulia.studia",
    "reviews.r3t": "sono quello che apre instagram al lavoro e perde 40 minuti. adesso il programma lavoro gira tutta la mattina, il telefono è praticamente morto fino a pranzo. e il capo non me l'ha imposto eh, l'ho scelto io",
    "reviews.r3n": "dan_dev",
    "reviews.r4t": "mi sono beccato a controllare il telefono mentre giocavo con mio figlio e mi sono sentito malissimo. ora blocco famiglia dalle 18 alle 21. mia figlia ha proprio notato che papà non guarda più il telefono",
    "reviews.r4n": "marco_papa",
    "reviews.r5t": "avrò cancellato instagram tipo 100 volte e l'ho sempre reinstallato. si vede che la soluzione non è cancellare, è bloccare. 3 settimane pulito e onestamente la voglia sta svanendo",
    "reviews.r5n": "chiara.m",
    "reviews.r6t": "la prima ora della giornata mi spariva nel telefono ancora prima di alzarmi dal letto. blocco mattutino dalle 7 alle 9, mi bevo il caffè e vado a camminare. riprendermi quell'ora è tutta un'altra vita",
    "reviews.r6n": "sara_corre",
    "reviews.r7t": "non riuscivo più a leggere, 2 pagine e la mano andava al telefono. blocco lettura serale e questo mese ho finito 3 libri. l'ultima volta era all'università",
    "reviews.r7n": "tommaso.legge",
    "reviews.r8t": "gli altri blocker li aggiravo in 2 tocchi, praticamente mentivo a me stesso. questo non lo puoi spegnere e sì all'inizio è fastidioso ma è l'unica cosa che abbia mai funzionato",
    "reviews.r8n": "cris_b",
    "reviews.r9t": "le statistiche mi hanno scioccato, 6h 40m al giorno. sceso a 3 ore in 2 mesi. vedere quel grafico che cala è stranamente la parte più motivante",
    "reviews.r9n": "francesca.k",
    "reviews.r10t": "non uscivo dal buco nero degli shorts così ho semplicemente bloccato youtube, problema risolto. sarebbero 5 stelle con un widget, per il resto zero lamentele",
    "reviews.r10n": "matteo_035",
    "reviews.note": "Esempi illustrativi. Questa sezione sarà aggiornata con vere recensioni dell'App Store dopo il lancio.",
    "faq.title": "Domande frequenti",
    "faq.q1": "Davvero non posso sbloccare prima?",
    "faq.a1": "È questa l'idea di fondo. Una volta iniziato, un programma programmato va avanti fino al suo orario di fine. Se potessi spegnerlo in due tocchi, sarebbe un promemoria, non un blocco. Imposta le durate con criterio.",
    "faq.q2": "Dove finiscono i miei dati?",
    "faq.a2": "Da nessuna parte. Pawlock non ha alcun sistema di account né server. I tuoi dati di Tempo di utilizzo sono elaborati sul tuo dispositivo tramite il framework di Apple, e noi non li vediamo mai.",
    "faq.q3": "Perché chiede il permesso per Tempo di utilizzo?",
    "faq.a3": "Bloccare le app è possibile solo tramite i controlli del sistema: Tempo di utilizzo (Family Sharing) di Apple su iPhone e il servizio di accessibilità su Android. Il permesso viene concesso al sistema del telefono ed è indispensabile per un blocco reale.",
    "faq.q4": "Cosa ottengo gratis?",
    "faq.a4": "3 blocchi istantanei al giorno, 1 programma automatico, blocco di app e siti web e Statistiche giornaliere di Tempo di utilizzo. Pro sblocca programmi illimitati e tutte le attuali funzioni Pro.",
    "faq.q5": "Come disdico l'abbonamento?",
    "faq.a5": "Dalle tue sottoscrizioni App Store o Google Play, come qualsiasi altra. Se disdici, Pro resta attivo fino alla fine del periodo pagato.",
    "faq.q6": "Quali dispositivi sono supportati?",
    "faq.a6": "Pawlock funziona su iPhone e su Android. Controlla la pagina dello store per i requisiti di versione.",
    "cta.title": "Riprenditi il tuo tempo.",
    "cta.sub": "Il tuo feed può aspettare. La tua vita no.",
    "cta.button": "Scarica Pawlock",
    "footer.tagline": "Meno schermo, più vita.",
    "footer.privacy": "Informativa sulla privacy",
    "footer.terms": "Termini d'uso",
    "footer.contact": "Contatti",
    "footer.rights": "Tutti i diritti riservati."
