    "reviews.title": "Что говорят люди",
    "reviews.sub": "Реальные истории из борьбы с бесконечной лентой.",
    "reviews.r1t": "залипал в ленте до 2 ночи каждый вечер. поставил расписание сна, которое блокирует всё в 23:00, первая неделя была тяжёлой но теперь я реально сплю по 7 часов",
    "reviews.r1n": "Алексей М.",
    "reviews.r2t": "сессия спасена. заблокировал телефон с 9 до 18 по будням, в первый день паниковал, к третьему привык. баллы за практику заметно выросли",
    "reviews.r2n": "Мария studies",
    "reviews.r3t": "я тот самый парень, который открывает инсту на работе и теряет 40 минут. рабочее расписание теперь на всё утро, телефон практически мёртв до обеда. и да, начальник меня не заставлял, я сам",
    "reviews.r3n": "Дмитрий codes",
    "reviews.r4t": "поймал себя на том что проверяю телефон пока играю с ребёнком и стало жутко стыдно. теперь семейная блокировка с 18 до 21. дочка реально заметила что папа больше не смотрит в телефон",
    "reviews.r4n": "Михаил, папа",
    "reviews.r5t": "удалял инстаграм раз 100 и всегда ставил заново. оказалось удаление не выход, блокировка, вот выход. 3 недели чисто и честно тяга уходит",
    "reviews.r5n": "Анна Миллер",
    "reviews.r6t": "первый час дня раньше исчезал в телефоне ещё до того как я вставал с кровати. утренняя блокировка с 7 до 9, пью кофе и иду гулять. вернуть себе этот час, это совсем другая жизнь",
    "reviews.r6n": "Ольга бежит",
    "reviews.r7t": "я больше не мог читать книги, 2 страницы и рука тянется к телефону. поставил вечернюю блокировку для чтения и прочитал 3 книги за месяц. последний раз такое было в универе",
    "reviews.r7n": "Артём reads",
    "reviews.r8t": "другие блокировщики я обходил в 2 касания, по сути врал сам себе. этот не отключить и да поначалу бесит но это единственное что вообще сработало",
    "reviews.r8n": "Сергей Б.",
    "reviews.r9t": "статистика шокировала, 6ч 40м в день. за 2 месяца снизил до 3 часов. смотреть как этот график ползёт вниз, странным образом самое мотивирующее",
    "reviews.r9n": "Екатерина К.",
    "reviews.r10t": "не мог выбраться из чёрной дыры шортсов так что просто заблокировал ютуб, проблема решена. было бы 5 звёзд с виджетом, в остальном ноль претензий",
    "reviews.r10n": "Иван_035",
    "reviews.note": "Иллюстративные примеры. Этот раздел будет обновлён реальными отзывами из App Store после запуска.",
    "faq.title": "Частые вопросы",
    "faq.q1": "Я правда не смогу разблокировать досрочно?",
    "faq.a1": "В этом основная идея. Как только запланированная программа началась, она работает до времени окончания. Если бы её можно было отключить в два касания, это было бы напоминание, а не блокировка. Задавайте длительность обдуманно.",
    "faq.q2": "Куда уходят мои данные?",
    "faq.a2": "Никуда. У Pawlock нет системы аккаунтов и нет серверов. Ваши данные Screen Time обрабатываются на вашем устройстве через фреймворк Apple, и мы их никогда не видим.",
    "faq.q3": "Почему приложение запрашивает разрешение Screen Time?",
    "faq.a3": "Блокировать приложения можно только средствами самой системы: «Экранное время» (Семейный доступ) Apple на iPhone и служба специальных возможностей на Android. Разрешение выдаётся системе телефона и обязательно для настоящей блокировки.",
    "faq.q4": "Что я получаю бесплатно?",
    "faq.a4": "3 мгновенные блокировки в день, 1 автоматическая программа, блокировка приложений и сайтов и Ежедневная статистика Экранного времени. Pro открывает неограниченное число программ и все текущие Pro-функции.",
    "faq.q5": "Как отменить подписку?",
    "faq.a5": "Через подписки App Store или Google Play, как и любую другую. При отмене Pro останется до конца оплаченного периода.",
    "faq.q6": "Какие устройства поддерживаются?",
    "faq.a6": "Pawlock работает на iPhone и на Android. Требования к версии смотрите на странице магазина.",
