    "reviews.r1t": "كنت أتصفّح حتى الثانية فجرًا كل ليلة. ضبطت جدول نوم يقفل كل شيء عند الحادية عشرة، وكان الأسبوع الأول صعبًا لكنني الآن أنام 7 ساعات فعلًا",
