    "hero.badge": "App blocker en schermtijdwachter voor iPhone en Android",
    "hero.title1": "Minder scherm,",
    "hero.title2": "meer ",
    "hero.title3": "leven.",
    "hero.sub": "Pawlock vergrendelt je afleidende apps en websites voor je. Vertrouw niet langer op wilskracht: bouw een systeem dat echt standhoudt.",
    "hero.cta": "Gratis downloaden",
    "hero.cta2": "Bekijk hoe het werkt",
