    "hero.trust3": "Gebouwd op de systeemfuncties van je eigen telefoon",
    "hero.trust4": "Geen advertenties",
    "problem.title": "Het ligt niet aan jou. Het ligt aan het ontwerp.",
    "problem.sub": "De apps die je tijd stelen zijn gebouwd door duizenden ingenieurs met één doel: je aan het scrollen houden. Wilskracht was nooit een eerlijk gevecht.",
    "problem.c1t": "“Even vijf minuten”",
    "problem.c1d": "Je opent het even. Een uur later zit je er nog steeds, en je weet niet eens meer wat je hebt gezien.",
    "problem.c2t": "Verwijderen werkt niet",
    "problem.c2d": "Je verwijdert de app vol vastberadenheid. Twee dagen later staat hij weer op je beginscherm.",
    "problem.c3t": "Herinneringen zijn te negeren",
    "problem.c3d": "Schermtijdwaarschuwingen en “neem een pauze”-pop-ups worden met één tik weggeklikt. Je hebt een vergrendeling nodig, geen suggestie.",
    "problem.stat1n": "4+ uur",
    "problem.stat1d": "besteedt de gemiddelde persoon elke dag opnieuw aan zijn telefoon",
    "problem.stat2n": "91 dagen",
    "problem.stat2d": "van je wakkere jaar verdwijnen bij dat tempo in het scherm",
    "problem.stat3n": "1 op de 4",
    "problem.stat3d": "wakkere uren gaat naar de telefoon, bij een wakkere dag van 16 uur",
    "problem.note": "De rekensom is simpel: 4 uur × 365 dagen = 1.460 uur per jaar. Reken een dag als 16 wakkere uren (de andere 8 zijn slaap) en dat zijn 91 volle wakkere dagen. De statistieken van Pawlock tonen jouw eigen getal, rechtstreeks van je apparaat.",
    "transition.title": "Aan de andere kant wacht je leven.",
    "transition.sub": "Je verliest niets door je telefoon weg te leggen. Je wint een hele dag terug.",
    "how.title": "Hoe Pawlock werkt",
    "how.sub": "Drie stappen. Daarna werkt het systeem zelfs als je motivatie dat niet doet.",
    "how.s1t": "Kies wat je afleidt",
    "how.s1d": "Kies apps, hele categorieën of websites met Apples officiële kiezer. Voeg elke site toe door het adres te typen.",
    "how.s2t": "Nu vergrendelen, of volgens schema",
    "how.s2d": "Eén tik voor een directe vergrendeling met timer, of maak automatische programma's: slapen, studeren, werken. Vensters die de nacht overspannen worden ondersteund.",
    "how.s3t": "Geen weg terug. Dat is de bedoeling.",
    "how.s3d": "Zodra een programma start, kan het niet vroegtijdig worden beëindigd. Pawlock staat op wacht zodat jij je leven kunt leven.",
    "features.title": "Alles wat je nodig hebt om je tijd terug te nemen",
    "features.sub": "Serieuze blokkering eronder, een vriendelijk gezicht erbovenop.",
    "features.f1t": "Directe vergrendeling",
    "features.f1d": "Eén tik vergrendelt je geselecteerde apps en sites. Draai aan het wiel om dagen, uren en minuten in te stellen en bekijk de focus-aftelling.",
    "features.f2t": "Gepersonaliseerde programmavoorstellen",
    "features.f2d": "Beantwoord een paar vragen tijdens de onboarding en Pawlock maakt automatisch een programmavoorstel op basis van je gewoonten, doelen en dagelijkse routine.",
    "features.f3t": "Streng van opzet",
    "features.f3d": "Een gestart programma kan niet vroegtijdig worden uitgezet. De vergrendeling die zich niet uit haar taak laat praten is degene die je gewoonten verandert.",
    "features.f4t": "Echte statistieken",
    "features.f4d": "Dagelijks, wekelijks en maandelijks gebruik op basis van Apple's Schermtijdgegevens. Echte cijfers van je apparaat, geen schattingen.",
    "features.f5t": "Websites ook",
    "features.f5d": "Afleiding zit niet alleen in apps. Blokkeer websites en hele categorieën ernaast, in dezelfde vergrendeling.",
    "features.f6t": "Privé standaard",
    "features.f6d": "Geen account, geen server, geen advertenties. Je schermtijdgegevens blijven op je iPhone, waar Apple ze bewaart.",
    "features.f7t": "Live aftellen",
    "features.f7d": "Volg elke vergrendeling via een Live Activity met de mascotte op het toegangsscherm en een compacte afteller in Dynamic Island.",
    "features.f8t": "Slimme dagelijkse meldingen",
    "features.f8d": "Ontvang dagelijks een nuttige melding op basis van je reeks, geblokkeerde pogingen of wekelijkse focusoverzicht.",
    "spot.auto.badge": "Automatisch",
    "spot.auto.title": "Op wacht, zelfs terwijl je slaapt.",
    "spot.auto.sub": "Stel je programma's één keer in en Pawlock neemt het over. Elke nacht en elke ochtend vergrendelt het precies op tijd. Je hoeft er niet eens aan te denken.",
    "spot.auto.b1": "Vensters over de nacht heen, zoals 23:00 → 07:00",
    "spot.auto.b2": "Een melding wanneer elk programma begint",
    "spot.auto.b3": "Elke dag, doordeweeks of weekenden met één tik",
    "spot.strict.badge": "Onbreekbaar",
    "spot.strict.title": "Een vergrendeling waar je je niet uit kunt praten.",
    "spot.strict.sub": "De meeste blokkers geven toe zodra je er echt in wilt. Pawlock niet. Zodra een programma start, is er geen vroege uitgang, geen ontsnapping met twee tikken. Dat is precies waarom het je gewoonten verandert.",
    "spot.strict.b1": "Gestarte programma's kunnen niet vroegtijdig worden beëindigd",
    "spot.strict.b2": "Gebouwd op Apples systeembrede Schermtijd",
    "spot.strict.b3": "Geen maas in de wet, geen “heel even dan”",
    "effect.title": "Zie de tijd die je terugwint",
    "effect.sub": "Pawlock toont je voor en na: hoe je gebruik verandert, je drukste uren, en wanneer je vergrendelde apps probeerde te openen. De teruggewonnen uren zien groeien is de beste motivatie die er is.",
    "effect.b1": "Vergelijking van voor en na",
    "effect.b2": "Je drukste gebruiksuren",
    "effect.b3": "Teruggewonnen tijd, dag voor dag",
    "effect.b4": "Snijd 1 uur per dag: 23 wakkere dagen per jaar terug",
