    "reviews.title": "Wat mensen zeggen",
    "reviews.sub": "Echte verhalen uit de strijd tegen het scrollen.",
    "reviews.r1t": "ik scrolde elke nacht door tot 2 uur. een slaapschema ingesteld dat om 23:00 alles vergrendelt, de eerste week was zwaar maar nu slaap ik echt 7 uur",
    "reviews.r1n": "daan_mkr",
    "reviews.r2t": "tentamenweek gered. mijn telefoon doordeweeks van 9 tot 6 vergrendeld, dag één paniek, dag drie gewend. mijn oefencijfers gingen flink omhoog",
    "reviews.r2n": "sanne.studeert",
    "reviews.r3t": "ik ben degene die op werk instagram opent en 40 minuten kwijt is. werkschema loopt nu de hele ochtend, telefoon is zo goed als dood tot de lunch. niemand die me dwong hoor, ik zelf",
    "reviews.r3n": "lars_codes",
    "reviews.r4t": "betrapte mezelf terwijl ik op mijn telefoon keek tijdens het spelen met mijn kind en voelde me rot. gezinsvergrendeling nu van 6 tot 9 uur s avonds. mijn dochter merkte echt dat papa niet meer op zn telefoon kijkt",
    "reviews.r4n": "mark_papa",
    "reviews.r5t": "heb instagram wel 100 keer verwijderd en steeds opnieuw geïnstalleerd. blijkt dat verwijderen niet het antwoord is, vergrendelen wel. 3 weken clean en de drang wordt echt minder",
    "reviews.r5n": "emma.jansen",
    "reviews.r6t": "het eerste uur van mijn dag verdween vroeger in mijn telefoon voordat ik zelfs uit bed was. ochtendvergrendeling 7 tot 9, ik drink mijn koffie en ga wandelen. dat uur weer bezitten is een ander leven",
    "reviews.r6n": "lotte_rent",
    "reviews.r7t": "ik kon geen boeken meer lezen, 2 paginas en mijn hand ging naar de telefoon. avondleesvergrendeling en ik heb deze maand 3 boeken uit. dat gebeurde voor het laatst tijdens mijn studie",
    "reviews.r7n": "thijs.leest",
    "reviews.r8t": "andere blokkers omzeilde ik in 2 tikken, gewoon mezelf voor de gek houden. deze kun je niet uitzetten en ja het is eerst irritant maar het is het enige dat ooit heeft gewerkt",
    "reviews.r8n": "bram_v",
    "reviews.r9t": "de stats schokten me, 6u 40m per dag. in 2 maanden terug naar 3 uur. die grafiek naar beneden zien gaan is vreemd genoeg het meest motiverende deel",
    "reviews.r9n": "fleur.k",
    "reviews.r10t": "kon niet uit het shorts-zwarte-gat ontsnappen dus heb youtube gewoon vergrendeld, probleem opgelost. met een widget zou het 5 sterren zijn, verder geen klachten",
    "reviews.r10n": "tim_035",
    "reviews.note": "Illustratieve voorbeelden. Deze sectie wordt na de lancering bijgewerkt met echte App Store-recensies.",
    "faq.title": "Veelgestelde vragen",
    "faq.q1": "Kan ik echt niet vroegtijdig ontgrendelen?",
    "faq.a1": "Dat is het kernidee. Zodra een gepland programma start, loopt het tot de eindtijd. Als je het in twee tikken kon uitzetten, zou het een herinnering zijn, geen vergrendeling. Stel je duur zorgvuldig in.",
    "faq.q2": "Waar gaan mijn gegevens naartoe?",
    "faq.a2": "Nergens. Pawlock heeft geen accountsysteem en geen servers. Je schermtijdgegevens worden op je apparaat verwerkt via Apples framework, en wij zien ze nooit.",
    "faq.q3": "Waarom vraagt het om toestemming voor Schermtijd?",
    "faq.a3": "Apps vergrendelen kan alleen via de systeemfuncties zelf: Apples Schermtijd (Gezinsdeling) op iPhone en de toegankelijkheidsservice op Android. De toestemming gaat naar het systeem van je telefoon en is nodig voor echte blokkering.",
    "faq.q4": "Wat krijg ik gratis?",
    "faq.a4": "3 directe vergrendelingen per dag, 1 automatisch programma, app- en websiteblokkering, en Dagelijkse Schermtijdstatistieken. Pro ontgrendelt onbeperkte programma's en alle huidige Pro-functies.",
    "faq.q5": "Hoe zeg ik mijn abonnement op?",
    "faq.a5": "Via je App Store- of Google Play-abonnementen, net als elk ander abonnement. Bij opzeggen blijft Pro actief tot het einde van de betaalde periode.",
    "faq.q6": "Welke apparaten worden ondersteund?",
    "faq.a6": "Pawlock werkt op iPhone en op Android. Bekijk de storepagina voor de actuele versievereisten.",
