    "problem.title": "To nie ty. To projekt.",
    "problem.sub": "Aplikacje kradnące twój czas zostały zbudowane przez tysiące inżynierów z jednym celem: żebyś dalej przewijał. Silna wola nigdy nie miała szans w tej walce.",
    "problem.c1t": "„Tylko pięć minut”",
    "problem.c1d": "Otwierasz ją na chwilę. Godzinę później wciąż tam jesteś i nawet nie pamiętasz, co widziałeś.",
    "problem.c2t": "Usuwanie nie działa",
    "problem.c2d": "Usuwasz aplikację pełen determinacji. Dwa dni później znów jest na twoim ekranie głównym.",
    "problem.c3t": "Przypomnienia da się zignorować",
