    "problem.stat2d": "twojego roku na jawie znika w ekranie przy takim tempie",
    "problem.stat3n": "1 na 4",
    "problem.stat3d": "godziny na jawie idą na telefon, przy 16-godzinnym dniu na jawie",
    "problem.note": "Matematyka jest prosta: 4 godziny × 365 dni = 1460 godzin rocznie. Licz dzień jako 16 godzin na jawie (pozostałe 8 to sen), a to 91 pełnych dni na jawie. Statystyki Pawlock pokazują twoją własną liczbę, prosto z twojego urządzenia.",
    "transition.title": "Po drugiej stronie czeka twoje życie.",
    "transition.sub": "Nic nie tracisz, odkładając telefon. Odzyskujesz cały dzień.",
    "how.title": "Jak działa Pawlock",
    "how.sub": "Trzy kroki. Potem system działa nawet wtedy, gdy twoja motywacja nie.",
    "how.s1t": "Wybierz to, co cię rozprasza",
    "how.s1d": "Wybierz aplikacje, całe kategorie lub strony za pomocą oficjalnego selektora Apple. Dodaj dowolną stronę, wpisując jej adres.",
    "how.s2t": "Zablokuj teraz albo według harmonogramu",
    "how.s2d": "Jedno dotknięcie dla natychmiastowej blokady z licznikiem lub twórz automatyczne programy: sen, nauka, praca. Okna nocne są obsługiwane.",
    "how.s3t": "Nie ma odwrotu. O to właśnie chodzi.",
    "how.s3d": "Gdy program się zacznie, nie można go zakończyć wcześniej. Pawlock stoi na straży, żebyś mógł iść żyć swoim życiem.",
    "features.title": "Wszystko, czego potrzebujesz, by odzyskać swój czas",
    "features.sub": "Poważne blokowanie pod spodem, przyjazna twarz na wierzchu.",
    "features.f1t": "Natychmiastowa blokada",
    "features.f1d": "Jedno dotknięcie blokuje wybrane aplikacje i strony. Ustaw dni, godziny, minuty na kółku i obserwuj odliczanie skupienia.",
    "features.f2t": "Spersonalizowane propozycje programów",
    "features.f2d": "Odpowiedz na kilka pytań podczas wdrażania, a Pawlock automatycznie utworzy propozycję programu dopasowaną do Twoich nawyków, celów i codziennego rytmu.",
    "features.f3t": "Rygorystyczny z założenia",
    "features.f3d": "Rozpoczętego programu nie można wyłączyć wcześniej. Blokada, której nie da się wygadać z jej zadania, to ta, która zmienia twoje nawyki.",
    "features.f4t": "Prawdziwe statystyki",
    "features.f4d": "Dzienne, tygodniowe i miesięczne użycie na podstawie danych Czasu przed ekranem Apple. Prawdziwe dane z urządzenia, nie szacunki.",
    "features.f5t": "Strony też",
    "features.f5d": "Rozproszenie to nie tylko aplikacje. Blokuj strony i całe kategorie obok nich, w tej samej blokadzie.",
    "features.f6t": "Prywatny domyślnie",
    "features.f6d": "Bez konta, bez serwera, bez reklam. Twoje dane Czasu przed ekranem zostają na twoim iPhonie, tam gdzie trzyma je Apple.",
    "features.f7t": "Odliczanie na żywo",
    "features.f7d": "Śledź każdą blokadę dzięki Live Activity z maskotką na ekranie blokady i kompaktowemu odliczaniu w Dynamic Island.",
    "features.f8t": "Inteligentne codzienne powiadomienia",
    "features.f8d": "Codziennie otrzymuj przydatne przypomnienie oparte na serii, zablokowanych próbach lub tygodniowym podsumowaniu skupienia.",
    "spot.auto.badge": "Automatyczny",
    "spot.auto.title": "Na straży, nawet gdy śpisz.",
    "spot.auto.sub": "Ustaw programy raz, a Pawlock przejmie stery. Każdej nocy i każdego ranka blokuje punktualnie. Nie musisz nawet pamiętać.",
    "spot.auto.b1": "Okna nocne, jak 23:00 → 7:00",
    "spot.auto.b2": "Powiadomienie, gdy każdy program się zaczyna",
    "spot.auto.b3": "Codziennie, dni robocze lub weekendy jednym dotknięciem",
    "spot.strict.badge": "Nie do złamania",
    "spot.strict.title": "Blokada, z której się nie wygadasz.",
    "spot.strict.sub": "Większość blokerów ustępuje w chwili, gdy naprawdę chcesz się dostać. Pawlock nie. Gdy program się zacznie, nie ma wcześniejszego wyjścia, nie ma ucieczki w dwa dotknięcia. To właśnie dlatego zmienia twoje nawyki.",
    "spot.strict.b1": "Rozpoczętych programów nie można zakończyć wcześniej",
    "spot.strict.b2": "Oparty na systemowym Czasie przed ekranem od Apple",
    "spot.strict.b3": "Bez luki, bez „tylko ten jeden raz”",
    "effect.title": "Zobacz czas, który odzyskujesz",
    "effect.sub": "Pawlock pokazuje twoje przed i po: jak zmienia się twoje użycie, twoje najbardziej zajęte godziny i kiedy próbowałeś otworzyć zablokowane aplikacje. Obserwowanie rosnących odzyskanych godzin to najlepsza motywacja, jaka istnieje.",
    "effect.b1": "Porównanie przed i po",
    "effect.b2": "Twoje najbardziej zajęte godziny użycia",
    "effect.b3": "Odzyskany czas, dzień po dniu",
    "effect.b4": "Odetnij 1 godzinę dziennie: 23 dni na jawie z powrotem każdego roku",
    "pricing.title": "Free vs Pro",
    "pricing.sub": "Zacznij za darmo. Przejdź wyżej, gdy twoje nawyki poproszą o więcej.",
    "pricing.freeName": "Free",
    "pricing.freePrice": "Za darmo na zawsze",
