    "reviews.title": "Co mówią ludzie",
    "reviews.sub": "Prawdziwe historie z walki z przewijaniem.",
    "reviews.r1t": "przewijałem do 2 w nocy każdej nocy. ustawiłem harmonogram snu, który blokuje wszystko o 23 i pierwszy tydzień był ciężki, ale teraz naprawdę śpię 7 godzin",
    "reviews.r1n": "Piotr K.",
    "reviews.r2t": "sesja mnie uratowała. zablokowałem telefon od 9 do 18 w dni robocze, pierwszego dnia panika, trzeciego już się przyzwyczaiłem. moje wyniki mocno poszły w górę",
    "reviews.r2n": "Anna Zielińska",
    "reviews.r3t": "jestem tym gościem, co otwiera instagrama w pracy i traci 40 minut. teraz harmonogram pracy leci przez cały ranek, telefon jest praktycznie martwy do lunchu. szef mi tego nie kazał, sam to zrobiłem",
    "reviews.r3n": "Marek W.",
    "reviews.r4t": "przyłapałem się na sprawdzaniu telefonu podczas zabawy z dzieckiem i poczułem się okropnie. teraz blokada rodzinna od 18 do 21. moja córka naprawdę zauważyła, że tata już nie patrzy w telefon",
    "reviews.r4n": "Tomasz Nowak",
    "reviews.r5t": "usuwałem instagrama z 100 razy i zawsze instalowałem z powrotem. okazuje się, że usuwanie to nie odpowiedź, blokowanie jest. 3 tygodnie czysto i szczerze mówiąc chęć słabnie",
    "reviews.r5n": "Katarzyna Wójcik",
    "reviews.r6t": "pierwsza godzina mojego dnia znikała w telefonie, zanim jeszcze wstałem z łóżka. poranna blokada 7 do 9, piję kawę i idę na spacer. odzyskanie tej godziny to zupełnie inne życie",
    "reviews.r6n": "Magdalena B.",
    "reviews.r7t": "nie potrafiłem już czytać książek, 2 strony i ręka sięgała po telefon. wieczorna blokada na czytanie i skończyłem 3 książki w tym miesiącu. ostatni raz tak było na studiach",
    "reviews.r7n": "Krzysztof Lewandowski",
    "reviews.r8t": "inne blokery obchodziłem w 2 dotknięcia, w zasadzie okłamując siebie. tego nie da się wyłączyć i tak, na początku jest irytujący, ale to jedyna rzecz, która kiedykolwiek zadziałała",
    "reviews.r8n": "Michał D.",
    "reviews.r9t": "statystyki mnie zszokowały, 6h 40m dziennie. spadło do 3 godzin w 2 miesiące. patrzenie, jak ten wykres leci w dół, jest dziwnie najbardziej motywujące",
    "reviews.r9n": "Aleksandra P.",
    "reviews.r10t": "nie mogłem uciec z czarnej dziury shortsów, więc po prostu zablokowałem youtube, problem rozwiązany. byłoby 5 gwiazdek z widżetem, poza tym zero uwag",
    "reviews.r10n": "Bartosz M.",
    "reviews.note": "Przykłady ilustracyjne. Ta sekcja zostanie zaktualizowana o prawdziwe recenzje z App Store po premierze.",
    "faq.title": "Najczęściej zadawane pytania",
    "faq.q1": "Czy naprawdę nie mogę odblokować wcześniej?",
    "faq.a1": "To główna idea. Gdy zaplanowany program się zacznie, działa do godziny zakończenia. Gdybyś mógł go wyłączyć w dwa dotknięcia, byłby przypomnieniem, nie blokadą. Ustawiaj czasy z rozwagą.",
    "faq.q2": "Dokąd trafiają moje dane?",
    "faq.a2": "Donikąd. Pawlock nie ma systemu kont ani serwerów. Twoje dane Czasu przed ekranem są przetwarzane na twoim urządzeniu przez framework Apple, a my nigdy ich nie widzimy.",
    "faq.q3": "Dlaczego prosi o pozwolenie na Czas przed ekranem?",
    "faq.a3": "Blokowanie aplikacji jest możliwe wyłącznie przez mechanizmy systemu: Czas przed ekranem (Chmura rodzinna) Apple na iPhonie i usługa ułatwień dostępu na Androidzie. Uprawnienie otrzymuje system telefonu i jest niezbędne do prawdziwej blokady.",
    "faq.q4": "Co dostaję za darmo?",
    "faq.a4": "3 blokady natychmiastowe dziennie, 1 automatyczny program, blokowanie aplikacji i stron oraz Dzienne statystyki Czasu przed ekranem. Pro odblokowuje nieograniczoną liczbę programów i wszystkie obecne funkcje Pro.",
    "faq.q5": "Jak anulować subskrypcję?",
    "faq.a5": "Przez subskrypcje App Store lub Google Play, jak każdą inną. Po anulowaniu Pro działa do końca opłaconego okresu.",
    "faq.q6": "Które urządzenia są obsługiwane?",
    "faq.a6": "Pawlock działa na iPhonie i na Androidzie. Aktualne wymagania znajdziesz na stronie sklepu.",
    "cta.title": "Odzyskaj swój czas.",
    "cta.sub": "Twój feed może poczekać. Twoje życie nie.",
    "cta.button": "Pobierz Pawlock",
    "footer.tagline": "Mniej ekranu, więcej życia.",
