    "spot.strict.b2": "สร้างบนเวลาหน้าจอระดับระบบของ Apple",
    "spot.strict.b3": "ไม่มีช่องโหว่ ไม่มี “ครั้งนี้ครั้งเดียว”",
    "effect.title": "ดูเวลาที่คุณทวงคืนมาได้",
    "effect.sub": "Pawlock แสดงก่อนและหลังของคุณ ว่าการใช้งานเปลี่ยนไปอย่างไร ชั่วโมงที่คุณยุ่งที่สุด และตอนที่คุณพยายามเปิดแอปที่ถูกล็อก การเฝ้าดูชั่วโมงที่ทวงคืนมาเพิ่มขึ้นคือแรงจูงใจที่ดีที่สุดที่มี",
    "effect.b1": "การเปรียบเทียบก่อนและหลัง",
    "effect.b2": "ชั่วโมงที่คุณใช้งานมากที่สุด",
    "effect.b3": "เวลาที่ทวงคืนมา ทีละวัน",
    "effect.b4": "ลดวันละ 1 ชั่วโมง ได้ 23 วันที่ตื่นคืนมาทุกปี",
    "pricing.title": "ฟรี vs Pro",
    "pricing.sub": "เริ่มฟรี อัปเกรดเมื่อนิสัยของคุณต้องการมากขึ้น",
