    "hero.title2": "nhiều ",
    "hero.title3": "cuộc sống.",
    "hero.sub": "Pawlock khóa những ứng dụng và trang web gây xao nhãng thay bạn. Đừng dựa vào ý chí nữa: hãy xây một hệ thống thực sự vững chắc.",
    "hero.cta": "Tải miễn phí",
    "hero.cta2": "Xem cách hoạt động",
    "hero.trust1": "Dữ liệu của bạn không bao giờ rời khỏi thiết bị",
    "hero.trust2": "Không cần tài khoản",
    "hero.trust3": "Dựa trên chính các điều khiển hệ thống của điện thoại bạn",
    "hero.trust4": "Không quảng cáo",
    "problem.title": "Không phải lỗi ở bạn. Đó là do thiết kế.",
    "problem.sub": "Những ứng dụng đang đánh cắp thời gian của bạn được hàng nghìn kỹ sư tạo ra với một mục tiêu: giữ bạn cứ lướt mãi. Ý chí chưa bao giờ là cuộc chiến công bằng.",
    "problem.c1t": "“Chỉ năm phút thôi”",
    "problem.c1d": "Bạn mở nó một lát. Một giờ sau bạn vẫn ở đó, và còn chẳng nhớ mình đã xem gì.",
    "problem.c2t": "Xóa đi cũng không được",
    "problem.c2d": "Bạn xóa ứng dụng với đầy quyết tâm. Hai ngày sau nó lại nằm trên màn hình chính.",
    "problem.c3t": "Nhắc nhở thì dễ bỏ qua",
    "problem.c3d": "Cảnh báo thời gian màn hình và cửa sổ “hãy nghỉ ngơi” bị gạt đi chỉ với một chạm. Bạn cần một khóa, không phải một lời gợi ý.",
    "problem.stat1n": "4+ giờ",
    "problem.stat1d": "là thời gian một người bình thường dành cho điện thoại mỗi ngày",
    "problem.stat2n": "91 ngày",
    "problem.stat2d": "trong năm thức của bạn biến mất vào màn hình với tốc độ đó",
    "problem.stat3n": "1 trong 4",
    "problem.stat3d": "giờ thức trôi vào điện thoại, tính theo ngày thức 16 giờ",
    "problem.note": "Phép tính rất đơn giản: 4 giờ × 365 ngày = 1.460 giờ mỗi năm. Tính một ngày là 16 giờ thức (8 giờ còn lại là ngủ) thì đó là 91 ngày thức trọn vẹn. Thống kê của Pawlock cho bạn thấy con số của chính mình, trực tiếp từ thiết bị.",
    "transition.title": "Ở phía bên kia, cuộc sống của bạn đang chờ.",
    "transition.sub": "Bạn không mất gì khi đặt điện thoại xuống. Bạn giành lại cả một ngày.",
    "how.title": "Pawlock hoạt động thế nào",
    "how.sub": "Ba bước. Sau đó, hệ thống vẫn chạy ngay cả khi động lực của bạn không còn.",
    "how.s1t": "Chọn thứ làm bạn xao nhãng",
    "how.s1d": "Chọn ứng dụng, cả danh mục hoặc trang web bằng công cụ chọn chính thức của Apple. Thêm bất kỳ trang nào bằng cách gõ địa chỉ của nó.",
    "how.s2t": "Khóa ngay, hoặc theo lịch",
    "how.s2d": "Một chạm để khóa tức thì kèm đồng hồ, hoặc tạo chương trình tự động: ngủ, học, làm việc. Hỗ trợ cả khung giờ qua đêm.",
    "how.s3t": "Không có đường lui. Đó chính là điểm mấu chốt.",
    "how.s3d": "Một khi chương trình bắt đầu, nó không thể kết thúc sớm. Pawlock đứng gác để bạn ra ngoài sống cuộc đời mình.",
    "features.title": "Mọi thứ bạn cần để giành lại thời gian",
    "features.sub": "Cơ chế chặn nghiêm túc bên trong, một gương mặt thân thiện bên ngoài.",
    "features.f1t": "Khóa tức thì",
    "features.f1d": "Một chạm khóa những ứng dụng và trang web bạn đã chọn. Xoay bánh xe để đặt ngày, giờ, phút, và ngắm đồng hồ tập trung đếm ngược.",
    "features.f2t": "Gợi ý chương trình được cá nhân hóa",
    "features.f2d": "Trả lời vài câu hỏi khi bắt đầu và Pawlock sẽ tự động tạo gợi ý chương trình phù hợp với thói quen, mục tiêu và lịch sinh hoạt hằng ngày của bạn.",
    "features.f3t": "Nghiêm khắc từ thiết kế",
    "features.f3d": "Một chương trình đã bắt đầu không thể tắt sớm. Chiếc khóa không thể bị dụ bỏ nhiệm vụ chính là chiếc khóa thay đổi thói quen của bạn.",
    "features.f4t": "Thống kê thật",
    "features.f4d": "Mức sử dụng hàng ngày, hàng tuần và hàng tháng từ dữ liệu Thời gian sử dụng của Apple. Số liệu thực từ thiết bị, không phải ước tính.",
    "features.f5t": "Cả trang web nữa",
    "features.f5d": "Xao nhãng không chỉ là ứng dụng. Chặn trang web và cả danh mục cùng với chúng, trong cùng một khóa.",
    "features.f6t": "Riêng tư mặc định",
    "features.f6d": "Không tài khoản, không máy chủ, không quảng cáo. Dữ liệu Thời gian sử dụng của bạn ở lại trên iPhone, nơi Apple giữ nó.",
    "features.f7t": "Đếm ngược trực tiếp",
    "features.f7d": "Theo dõi mỗi lần khóa bằng Live Activity có linh vật trên Màn hình khóa và bộ đếm ngược gọn trong Dynamic Island.",
    "features.f8t": "Thông báo hằng ngày thông minh",
    "features.f8d": "Nhận lời nhắc hữu ích mỗi ngày dựa trên chuỗi thành tích, lượt truy cập bị chặn hoặc bản tóm tắt tập trung hằng tuần.",
    "spot.auto.badge": "Tự động",
    "spot.auto.title": "Canh gác, ngay cả khi bạn ngủ.",
    "spot.auto.sub": "Đặt chương trình một lần và Pawlock lo phần còn lại. Mỗi đêm và mỗi sáng nó khóa đúng giờ. Bạn thậm chí không cần phải nhớ.",
    "spot.auto.b1": "Khung giờ qua đêm, như 23h → 7h",
    "spot.auto.b2": "Một thông báo khi mỗi chương trình bắt đầu",
    "spot.auto.b3": "Mỗi ngày, ngày trong tuần hoặc cuối tuần chỉ với một chạm",
    "spot.strict.badge": "Không thể phá vỡ",
    "spot.strict.title": "Chiếc khóa bạn không thể lý sự để thoát.",
    "spot.strict.sub": "Hầu hết ứng dụng chặn đều đầu hàng ngay khi bạn thực sự muốn vào. Pawlock thì không. Một khi chương trình bắt đầu, không có lối thoát sớm, không có đường trốn hai chạm. Đó chính là lý do nó thay đổi thói quen của bạn.",
    "spot.strict.b1": "Chương trình đã bắt đầu không thể kết thúc sớm",
    "spot.strict.b2": "Xây dựng trên Thời gian sử dụng cấp hệ thống của Apple",
    "spot.strict.b3": "Không kẽ hở, không có “chỉ lần này thôi”",
    "effect.title": "Thấy được thời gian bạn giành lại",
    "effect.sub": "Pawlock cho bạn thấy trước và sau: cách mức sử dụng của bạn thay đổi, những giờ bận rộn nhất, và khi bạn cố mở các ứng dụng đã khóa. Nhìn những giờ giành lại tăng dần là động lực tốt nhất có thể có.",
    "effect.b1": "So sánh trước và sau",
