    "why.title": "Vì sao chọn Pawlock?",
    "why.sub": "Một so sánh công bằng với các ứng dụng chặn thông thường.",
    "why.colOthers": "Ứng dụng chặn thông thường",
    "why.r1": "Khóa cấp hệ thống qua công nghệ Thời gian sử dụng chính thức của Apple",
    "why.r2": "Khóa không thể kết thúc sớm",
    "why.r3": "Lịch tự động với khung giờ qua đêm",
    "why.r4": "Hoạt động không cần tài khoản hay đăng ký",
