    "reviews.title": "Mọi người nói gì",
    "reviews.sub": "Những câu chuyện thật từ cuộc chiến chống lại việc lướt mãi.",
    "reviews.r1t": "trước mình lướt tới 2 giờ sáng mỗi đêm. đặt lịch ngủ khóa hết mọi thứ lúc 11 giờ, tuần đầu khó chịu thật nhưng giờ mình ngủ được 7 tiếng rồi",
    "reviews.r1n": "Nguyễn Văn An",
    "reviews.r2t": "cứu mình mùa thi cuối kỳ. khóa điện thoại từ 9 giờ tới 6 giờ các ngày trong tuần, ngày đầu hoảng loạn, tới ngày thứ ba là quen. điểm ôn tập lên hẳn",
    "reviews.r2n": "Trần Thị Mai",
    "reviews.r3t": "mình là kiểu người mở instagram lúc làm việc rồi mất 40 phút. giờ lịch làm việc chạy cả buổi sáng, điện thoại coi như chết tới trưa. sếp không bắt đâu nhé, tự mình làm đó",
    "reviews.r3n": "Lê Minh Đức",
    "reviews.r4t": "bắt gặp mình cầm điện thoại lúc chơi với con và thấy tệ kinh khủng. giờ khóa gia đình từ 6 tới 9 giờ tối. con gái mình còn nhận ra là bố không nhìn điện thoại nữa",
    "reviews.r4n": "Phạm Thu Hà",
    "reviews.r5t": "xóa instagram cả trăm lần rồi lại cài lại. hóa ra xóa không phải đáp án, khóa mới là. 3 tuần sạch và thật sự cơn thèm đang nhạt dần",
    "reviews.r5n": "Hoàng Thị Lan",
    "reviews.r6t": "giờ đầu tiên trong ngày của mình từng tan biến vào điện thoại trước cả khi ra khỏi giường. giờ khóa buổi sáng 7 tới 9 giờ, mình uống cà phê rồi đi dạo. giành lại được giờ đó là một cuộc đời khác",
    "reviews.r6n": "Vũ Ngọc Quỳnh",
    "reviews.r7t": "mình không đọc sách nổi nữa, 2 trang là tay lại với lấy điện thoại. giờ khóa đọc buổi tối, tháng này mình đọc xong 3 cuốn. lần cuối làm được vậy là hồi đại học",
    "reviews.r7n": "Đặng Quốc Bảo",
    "reviews.r8t": "mấy app chặn khác mình lách được trong 2 chạm, kiểu tự lừa mình vậy. app này không tắt được và đúng là lúc đầu khó chịu thật nhưng là thứ duy nhất từng có tác dụng",
    "reviews.r8n": "Bùi Anh Tuấn",
    "reviews.r9t": "thống kê làm mình sốc, 6 tiếng 40 phút một ngày. giảm còn 3 tiếng sau 2 tháng. nhìn biểu đồ đó đi xuống kỳ lạ thay lại là phần tạo động lực nhất",
    "reviews.r9n": "Ngô Thị Hương",
    "reviews.r10t": "không thoát nổi cái hố đen shorts nên mình khóa luôn youtube, xong vấn đề. có thêm widget thì 5 sao, còn lại không có gì để phàn nàn",
    "reviews.r10n": "Đỗ Hải Nam",
    "reviews.note": "Ví dụ minh họa. Mục này sẽ được cập nhật bằng các đánh giá thật từ App Store sau khi ra mắt.",
    "faq.title": "Câu hỏi thường gặp",
    "faq.q1": "Thật sự không thể mở khóa sớm sao?",
    "faq.a1": "Đó là ý tưởng cốt lõi. Một khi chương trình theo lịch bắt đầu, nó chạy đến giờ kết thúc. Nếu bạn có thể tắt nó trong hai chạm, thì nó là lời nhắc, không phải khóa. Hãy đặt thời lượng một cách cân nhắc.",
    "faq.q2": "Dữ liệu của tôi đi đâu?",
    "faq.a2": "Không đi đâu cả. Pawlock không có hệ thống tài khoản và không có máy chủ. Dữ liệu Thời gian sử dụng của bạn được xử lý ngay trên thiết bị qua khung của Apple, và chúng tôi không bao giờ thấy nó.",
    "faq.q3": "Vì sao ứng dụng xin quyền Thời gian sử dụng?",
    "faq.a3": "Khóa ứng dụng chỉ khả thi qua chính các điều khiển của hệ thống: Screen Time (Chia sẻ gia đình) của Apple trên iPhone, và dịch vụ trợ năng trên Android. Quyền được cấp cho hệ thống điện thoại và là bắt buộc để chặn thật sự.",
    "faq.q4": "Tôi nhận được gì khi dùng miễn phí?",
    "faq.a4": "3 lượt khóa tức thì mỗi ngày, 1 chương trình tự động, chặn ứng dụng và trang web, cùng Thống kê Thời gian sử dụng hằng ngày. Pro mở khóa chương trình tự động không giới hạn và mọi tính năng Pro hiện có.",
    "faq.q5": "Làm sao để hủy gói đăng ký?",
    "faq.a5": "Qua đăng ký App Store hoặc Google Play, như mọi đăng ký khác. Nếu hủy, Pro vẫn hoạt động đến hết kỳ đã thanh toán.",
    "faq.q6": "Những thiết bị nào được hỗ trợ?",
    "faq.a6": "Pawlock chạy trên iPhone và Android. Xem trang cửa hàng để biết yêu cầu phiên bản hiện tại.",
    "cta.title": "Giành lại thời gian của bạn.",
    "cta.sub": "Bảng tin có thể chờ. Cuộc sống của bạn thì không.",
    "cta.button": "Tải Pawlock",
    "footer.tagline": "Ít màn hình, nhiều cuộc sống.",
    "footer.privacy": "Chính sách quyền riêng tư",
    "footer.terms": "Điều khoản sử dụng",
    "footer.contact": "Liên hệ",
    "footer.rights": "Bảo lưu mọi quyền."
