    "hero.badge": "Appblockerare och skärmtidsvakt för iPhone och Android",
    "hero.title1": "Mindre skärm,",
    "hero.title2": "mer ",
    "hero.title3": "liv.",
    "hero.sub": "Pawlock låser dina distraherande appar och webbplatser åt dig. Sluta förlita dig på viljestyrka: bygg ett system som verkligen håller.",
    "hero.cta": "Ladda ner gratis",
    "hero.cta2": "Se hur det fungerar",
    "hero.trust1": "Din data lämnar aldrig din enhet",
    "hero.trust2": "Inget konto behövs",
    "hero.trust3": "Byggd på telefonens egna systemfunktioner",
    "hero.trust4": "Inga annonser",
    "problem.title": "Det är inte du. Det är designen.",
    "problem.sub": "Apparna som stjäl din tid byggdes av tusentals ingenjörer med ett enda mål: att hålla dig scrollande. Viljestyrka var aldrig en rättvis match.",
    "problem.c1t": "”Bara fem minuter”",
    "problem.c1d": "Du öppnar den ett ögonblick. En timme senare är du kvar och minns inte ens vad du såg.",
    "problem.c2t": "Att radera fungerar inte",
    "problem.c2d": "Du raderar appen full av beslutsamhet. Två dagar senare är den tillbaka på din hemskärm.",
    "problem.c3t": "Påminnelser går att ignorera",
    "problem.c3d": "Skärmtidsvarningar och ”ta en paus”-popuprutor avfärdas med ett tryck. Du behöver ett lås, inte ett förslag.",
    "problem.stat1n": "4+ timmar",
    "problem.stat1d": "är vad en genomsnittsperson lägger på sin telefon varje enda dag",
    "problem.stat2n": "91 dagar",
    "problem.stat2d": "av ditt vakna år försvinner in i skärmen i den takten",
    "problem.stat3n": "1 av 4",
    "problem.stat3d": "vakna timmar går till telefonen, på ett 16 timmars vaket dygn",
    "problem.note": "Matematiken är enkel: 4 timmar × 365 dagar = 1 460 timmar om året. Räkna en dag som 16 vakna timmar (de andra 8 är sömn) och det blir 91 hela vakna dagar. Pawlocks statistik visar din egen siffra, direkt från din enhet.",
    "transition.title": "På andra sidan väntar ditt liv.",
    "transition.sub": "Du förlorar ingenting på att lägga ner telefonen. Du vinner tillbaka en hel dag.",
    "how.title": "Så fungerar Pawlock",
    "how.sub": "Tre steg. Sedan jobbar systemet även när din motivation inte gör det.",
    "how.s1t": "Välj det som distraherar dig",
    "how.s1d": "Välj appar, hela kategorier eller webbplatser med Apples officiella väljare. Lägg till valfri sida genom att skriva dess adress.",
    "how.s2t": "Lås nu, eller enligt schema",
    "how.s2d": "Ett tryck för ett omedelbart lås med timer, eller skapa automatiska program: sömn, plugg, arbete. Perioder över natten stöds.",
    "how.s3t": "Ingen väg tillbaka. Det är hela poängen.",
    "how.s3d": "När ett program väl har startat kan det inte avslutas i förtid. Pawlock står på vakt så att du kan gå och leva ditt liv.",
    "features.title": "Allt du behöver för att ta tillbaka din tid",
    "features.sub": "Seriös blockering under huven, ett vänligt ansikte utåt.",
    "features.f1t": "Omedelbart lås",
    "features.f1d": "Ett tryck låser dina valda appar och webbplatser. Snurra på hjulet för att ställa in dagar, timmar och minuter, och se fokusnedräkningen.",
    "features.f2t": "Personliga programförslag",
    "features.f2d": "Svara på några frågor under introduktionen så skapar Pawlock automatiskt ett programförslag utifrån dina vanor, mål och dagliga rutiner.",
    "features.f3t": "Strikt av design",
    "features.f3d": "Ett startat program kan inte stängas av i förtid. Låset som inte går att prata sig ur sitt jobb är det som förändrar dina vanor.",
    "features.f4t": "Verklig statistik",
    "features.f4d": "Daglig, veckovis och månatlig användning från Apples Skärmtidsdata. Verkliga siffror från din enhet, inga uppskattningar.",
    "features.f5t": "Webbplatser också",
    "features.f5d": "Distraktion är inte bara appar. Blockera webbplatser och hela kategorier vid sidan av dem, i samma lås.",
    "features.f6t": "Privat som standard",
    "features.f6d": "Inget konto, ingen server, inga annonser. Din skärmtidsdata stannar på din iPhone, där Apple förvarar den.",
    "features.f7t": "Nedräkning i realtid",
    "features.f7d": "Följ varje lås med en Live Activity med maskoten på låsskärmen och en kompakt nedräkning i Dynamic Island.",
    "features.f8t": "Smarta dagliga notiser",
    "features.f8d": "Få en användbar daglig påminnelse baserad på din svit, blockerade försök eller veckans fokussammanfattning.",
    "spot.auto.badge": "Automatiskt",
    "spot.auto.title": "På vakt, även medan du sover.",
    "spot.auto.sub": "Ställ in dina program en gång och Pawlock tar över. Varje natt och varje morgon låser det precis i tid. Du behöver inte ens komma ihåg.",
    "spot.auto.b1": "Perioder över natten, som 23:00 → 07:00",
    "spot.auto.b2": "En avisering när varje program börjar",
    "spot.auto.b3": "Varje dag, vardagar eller helger med ett tryck",
    "spot.strict.badge": "Obrytbart",
    "spot.strict.title": "Ett lås du inte kan prata dig ur.",
    "spot.strict.sub": "De flesta blockerare viker sig i samma stund du verkligen vill in. Pawlock gör inte det. När ett program väl har startat finns ingen väg ut i förtid, ingen flykt med två tryck. Det är hela anledningen till att det förändrar dina vanor.",
    "spot.strict.b1": "Startade program kan inte avslutas i förtid",
    "spot.strict.b2": "Byggd på Apples Skärmtid på systemnivå",
    "spot.strict.b3": "Inget kryphål, inget ”bara den här gången”",
    "effect.title": "Se tiden du vinner tillbaka",
    "effect.sub": "Pawlock visar ditt före och efter: hur din användning förändras, dina mest aktiva timmar och när du försökte öppna låsta appar. Att se de återvunna timmarna växa är den bästa motivationen som finns.",
    "effect.b1": "Jämförelse mellan före och efter",
    "effect.b2": "Dina mest aktiva användningstimmar",
    "effect.b3": "Återvunnen tid, dag för dag",
    "effect.b4": "Skär en timme om dagen: 23 vakna dagar tillbaka varje år",
