    "why.sub": "En rättvis jämförelse med typiska blockerarappar.",
    "why.colOthers": "Typiska blockerare",
    "why.r1": "Lås på systemnivå via Apples officiella Skärmtid-teknik",
    "why.r2": "Lås kan inte avslutas i förtid",
