    "reviews.title": "Vad folk säger",
    "reviews.sub": "Verkliga berättelser från kampen mot scrollandet.",
    "reviews.r1t": "jag scrollade till 02 varje enda natt. satte ett sömnschema som låser allt kl 23 och första veckan var tuff men nu sover jag faktiskt 7 timmar",
    "reviews.r1n": "erik_lund",
    "reviews.r2t": "tentaveckan räddade mig. låste telefonen 9 till 18 på vardagar, fick panik dag ett, vande mig dag tre. mina övningsresultat sköt i höjden",
    "reviews.r2n": "sara.pluggar",
    "reviews.r3t": "jag är typen som öppnar instagram på jobbet och tappar 40 minuter. arbetsschemat går hela förmiddagen nu, telefonen är i princip död till lunch. chefen tvingade mig inte förresten, jag gjorde det själv",
    "reviews.r3n": "johan_kodar",
    "reviews.r4t": "kom på mig själv att kolla telefonen medan jag lekte med mitt barn och mådde hemskt. familjelås 18 till 21 nu. min dotter märkte faktiskt att pappa inte tittar på telefonen längre",
    "reviews.r4n": "mikael_t_pappa",
    "reviews.r5t": "raderade instagram typ 100 gånger och installerade alltid om. visar sig att radera inte är svaret, att låsa är det. 3 veckor ren och ärligt talat bleknar suget",
    "reviews.r5n": "jessica.andersson",
    "reviews.r6t": "första timmen av min dag försvann in i telefonen innan jag ens gick upp ur sängen. morgonlås 7 till 9, jag dricker mitt kaffe och går en promenad. att äga den timmen igen är ett annat liv",
    "reviews.r6n": "anna_springer",
    "reviews.r7t": "jag kunde inte läsa böcker längre, 2 sidor och handen sträckte sig efter telefonen. kvällsläslås och jag läste ut 3 böcker den här månaden. senast det hände var på universitetet",
    "reviews.r7n": "tomas.laser",
    "reviews.r8t": "andra blockerare kunde jag kringgå med 2 tryck, ljög i princip för mig själv. den här går inte att stänga av och ja det är irriterande i början men det är det enda som någonsin fungerat",
    "reviews.r8n": "kristoffer_b",
    "reviews.r9t": "statistiken chockade mig, 6h 40m om dagen. nere på 3 timmar på 2 månader. att se den grafen gå neråt är konstigt nog det mest motiverande",
    "reviews.r9n": "rebecka.k",
    "reviews.r10t": "kunde inte ta mig ur shorts-svarta-hålet så jag låste bara youtube, problem löst. hade blivit 5 stjärnor med en widget, annars inga klagomål",
    "reviews.r10n": "tobias_035",
    "reviews.note": "Illustrativa exempel. Det här avsnittet uppdateras med verkliga App Store-recensioner efter lansering.",
    "faq.title": "Vanliga frågor",
    "faq.q1": "Kan jag verkligen inte låsa upp i förtid?",
    "faq.a1": "Det är grundidén. När ett schemalagt program väl har startat körs det till sin sluttid. Om du kunde stänga av det med två tryck vore det en påminnelse, inte ett lås. Sätt dina längder genomtänkt.",
    "faq.q2": "Vart tar min data vägen?",
    "faq.a2": "Ingenstans. Pawlock har inget kontosystem och inga servrar. Din skärmtidsdata bearbetas på din enhet via Apples ramverk, och vi ser den aldrig.",
    "faq.q3": "Varför frågar den efter behörighet till Skärmtid?",
    "faq.a3": "Att låsa appar går bara via systemets egna funktioner: Apples Skärmtid (Familjedelning) på iPhone och tillgänglighetstjänsten på Android. Behörigheten ges till telefonens system och krävs för verklig blockering.",
    "faq.q4": "Vad får jag gratis?",
    "faq.a4": "3 omedelbara lås per dag, 1 automatiskt program, blockering av appar och webbplatser, samt Daglig Skärmtidsstatistik. Pro låser upp obegränsat antal program och alla nuvarande Pro-funktioner.",
