    "reviews.title": "Hvad folk siger",
    "reviews.sub": "Ægte historier fra kampen mod scrollingen.",
    "reviews.r1t": "jeg scrollede til kl. 2 hver eneste nat. lavede en søvntidsplan der låser alt kl. 23 og den første uge var hård men nu sover jeg faktisk 7 timer",
    "reviews.r1n": "mads_k",
    "reviews.r2t": "eksamensugen reddede mig. låste min telefon 9 til 18 på hverdage, gik i panik dag et, var vant til det dag tre. mine karakterer røg op",
    "reviews.r2n": "sofie.laeser",
    "reviews.r3t": "jeg er ham der åbner instagram på arbejdet og mister 40 minutter. arbejdstidsplanen kører hele formiddagen nu, telefonen er stort set død til frokost. min chef bad mig ikke om det btw, det gjorde jeg selv",
    "reviews.r3n": "lars_koder",
    "reviews.r4t": "opdagede at jeg tjekkede telefonen mens jeg legede med mit barn og fik det forfærdeligt. familielås fra 18 til 21 nu. min datter lagde faktisk mærke til at far ikke kigger på sin telefon længere",
    "reviews.r4n": "kristian_far",
    "reviews.r5t": "slettede instagram vel 100 gange og geninstallerede altid. viser sig at slette ikke er svaret, det er at låse. 3 uger clean og ærligt talt er trangen ved at forsvinde",
    "reviews.r5n": "ida.nielsen",
    "reviews.r6t": "den første time af min dag plejede at forsvinde ind i telefonen før jeg overhovedet kom ud af sengen. morgenlås 7 til 9, jeg drikker min kaffe og går en tur. at eje den time igen er et helt andet liv",
    "reviews.r6n": "anne_loeber",
    "reviews.r7t": "jeg kunne ikke læse bøger mere, 2 sider og min hånd greb efter telefonen. aftenlæselås og jeg færdiggjorde 3 bøger denne måned. sidste gang det skete var på studiet",
    "reviews.r7n": "thomas.laeser",
    "reviews.r8t": "andre blokeringer kunne jeg omgå med 2 tryk, jeg løj bare for mig selv. denne her kan man ikke slå fra og ja det er irriterende i starten men det er det eneste der nogensinde har virket",
    "reviews.r8n": "christian_b",
    "reviews.r9t": "statistikken chokerede mig, 6t 40m om dagen. nede på 3 timer på 2 måneder. at se den graf falde er mærkeligt nok det mest motiverende",
    "reviews.r9n": "rikke.j",
    "reviews.r10t": "kunne ikke slippe ud af shorts-hullet så jeg låste bare youtube, problem løst. ville være 5 stjerner med en widget, ellers ingen klager",
    "reviews.r10n": "tobias_035",
    "reviews.note": "Illustrative eksempler. Denne sektion opdateres med ægte App Store-anmeldelser efter lanceringen.",
    "faq.title": "Ofte stillede spørgsmål",
    "faq.q1": "Kan jeg virkelig ikke låse op før tid?",
    "faq.a1": "Det er kerneidéen. Når et planlagt program er startet, kører det til sit sluttidspunkt. Hvis du kunne slå det fra med to tryk, ville det være en påmindelse, ikke en lås. Vælg dine varigheder med omtanke.",
    "faq.q2": "Hvor havner mine data?",
    "faq.a2": "Ingen steder. Pawlock har intet kontosystem og ingen servere. Dine skærmtidsdata behandles på din enhed gennem Apples framework, og vi ser dem aldrig.",
    "faq.q3": "Hvorfor beder den om tilladelse til Skærmtid?",
    "faq.a3": "At låse apps kan kun ske via systemets egne funktioner: Apples Skærmtid (Familiedeling) på iPhone og tilgængelighedstjenesten på Android. Tilladelsen gives til telefonens system og er nødvendig for reel blokering.",
    "faq.q4": "Hvad får jeg gratis?",
    "faq.a4": "3 øjeblikkelige låse om dagen, 1 automatisk program, blokering af apps og websteder samt Daglig Skærmtidsstatistik. Pro låser op for ubegrænset antal programmer og alle nuværende Pro-funktioner.",
    "faq.q5": "Hvordan opsiger jeg mit abonnement?",
    "faq.a5": "Via dine App Store- eller Google Play-abonnementer, som ethvert andet. Opsiger du, gælder Pro perioden ud.",
    "faq.q6": "Hvilke enheder understøttes?",
    "faq.a6": "Pawlock kører på iPhone og på Android. Se butikssiden for aktuelle versionskrav.",
