    "problem.title": "Vika ei ole sinussa. Vika on suunnittelussa.",
    "problem.sub": "Aikaasi varastavat sovellukset ovat tuhansien insinöörien rakentamia, ja heillä on yksi tavoite: pitää sinut vierittämässä. Tahdonvoima ei koskaan ollut reilu taistelu.",
    "problem.c1t": "”Vain viisi minuuttia”",
    "problem.c1d": "Avaat sen hetkeksi. Tunti myöhemmin olet yhä siellä, etkä edes muista, mitä näit.",
    "problem.c2t": "Poistaminen ei toimi",
    "problem.c2d": "Poistat sovelluksen päättäväisenä. Kaksi päivää myöhemmin se on takaisin kotinäytölläsi.",
    "problem.c3t": "Muistutukset on helppo sivuuttaa",
    "problem.c3d": "Ruutuaikavaroitukset ja ”pidä tauko” -ponnahdukset ohitetaan yhdellä napautuksella. Tarvitset lukituksen, et ehdotusta.",
