    "problem.stat3d": "valvetunnista menee puhelimeen, kun valvepäivä on 16 tuntia",
    "problem.note": "Matematiikka on yksinkertaista: 4 tuntia × 365 päivää = 1 460 tuntia vuodessa. Laske päiväksi 16 valvetuntia (loput 8 ovat unta), ja siitä tulee 91 täyttä valvepäivää. Pawlockin tilastot näyttävät oman lukusi, suoraan laitteeltasi.",
    "transition.title": "Toisella puolella elämäsi odottaa.",
    "transition.sub": "Et menetä mitään laskemalla puhelimen kädestäsi. Saat takaisin kokonaisen päivän.",
    "how.title": "Miten Pawlock toimii",
    "how.sub": "Kolme vaihetta. Sen jälkeen järjestelmä toimii, vaikka motivaatiosi ei toimisi.",
    "how.s1t": "Valitse, mikä häiritsee sinua",
    "how.s1d": "Valitse sovelluksia, kokonaisia kategorioita tai verkkosivustoja Applen virallisella valitsimella. Lisää mikä tahansa sivusto kirjoittamalla sen osoite.",
    "how.s2t": "Lukitse nyt tai aikataulun mukaan",
