    "features.f2t": "Personoidut ohjelmaehdotukset",
    "features.f2d": "Vastaa muutamaan kysymykseen käyttöönotossa, niin Pawlock luo automaattisesti ohjelmaehdotuksen tapojesi, tavoitteidesi ja päivärutiinisi perusteella.",
    "features.f3t": "Tiukka suunnittelultaan",
