    "features.f6t": "Yksityinen oletuksena",
    "features.f6d": "Ei tiliä, ei palvelinta, ei mainoksia. Ruutuaikatietosi pysyvät iPhonessasi, missä Apple ne säilyttää.",
    "features.f7t": "Reaaliaikaiset lähtölaskennat",
    "features.f7d": "Seuraa jokaista lukitusta maskotin sisältävällä Live Activity -näkymällä lukitusnäytössä ja tiiviillä laskurilla Dynamic Islandissa.",
    "features.f8t": "Älykkäät päivittäiset ilmoitukset",
    "features.f8d": "Saat päivittäin hyödyllisen muistutuksen putkesi, estettyjen yritysten tai viikoittaisen keskittymisyhteenvedon perusteella.",
