    "spot.auto.sub": "Aseta ohjelmasi kerran ja Pawlock ottaa ohjat. Joka yö ja joka aamu se lukitsee juuri ajallaan. Sinun ei tarvitse edes muistaa.",
    "spot.auto.b1": "Yön yli jatkuvat jaksot, kuten 23 → 7",
    "spot.auto.b2": "Ilmoitus, kun jokainen ohjelma alkaa",
    "spot.auto.b3": "Joka päivä, arkipäivät tai viikonloput yhdellä napautuksella",
