    "spot.strict.title": "Lukitus, josta et voi puhua itseäsi ulos.",
    "spot.strict.sub": "Useimmat estäjät antavat periksi heti, kun todella haluat sisään. Pawlock ei. Kun ohjelma alkaa, ei ole etuajan uloskäyntiä, ei kahden napautuksen pakoreittiä. Juuri siksi se muuttaa tapojasi.",
