    "reviews.title": "Mitä ihmiset sanovat",
    "reviews.sub": "Todellisia tarinoita taistelusta vierittämistä vastaan.",
    "reviews.r1t": "vieritin joka ikinen ilta kahteen asti. asetin uniaikataulun joka lukitsee kaiken yhdeltätoista, eka viikko oli rankka mutta nyt nukun oikeasti 7 tuntia",
    "reviews.r1n": "mikko_h",
    "reviews.r2t": "tenttiviikko pelasti minut. lukitsin puhelimen arkisin 9-18, panikoin ekana päivänä, kolmanteen mennessä tottunut. harjoituspisteeni nousivat rajusti",
    "reviews.r2n": "laura.lukee",
    "reviews.r3t": "olen se tyyppi joka avaa instagramin töissä ja menettää 40 minuuttia. työaikataulu pyörii nyt koko aamun, puhelin on käytännössä kuollut lounaaseen asti. pomo ei muuten pakottanut, tein sen itse",
    "reviews.r3n": "juha_koodaa",
    "reviews.r4t": "huomasin vilkuilevani puhelinta lapseni kanssa leikkiessä ja tuntui kamalalta. perhelukitus nyt 18-21. tyttäreni oikeasti huomasi ettei isä katso enää puhelinta",
    "reviews.r4n": "antti_isa",
    "reviews.r5t": "poistin instagramin varmaan 100 kertaa ja asensin aina uudestaan. käy ilmi ettei poistaminen ole vastaus, lukitseminen on. 3 viikkoa puhtaana ja rehellisesti sanottuna himo hiipuu",
    "reviews.r5n": "anni.virtanen",
    "reviews.r6t": "päiväni eka tunti katosi ennen puhelimeen ennen kuin nousin edes sängystä. aamulukitus 7-9, juon kahvini ja lähden kävelylle. sen tunnin omistaminen taas on eri elämä",
    "reviews.r6n": "emma_juoksee",
    "reviews.r7t": "en enää pystynyt lukemaan kirjoja, 2 sivua ja käteni haki puhelinta. iltalukitus lukemiselle ja luin 3 kirjaa tässä kuussa. viimeksi noin kävi opiskeluaikoina",
    "reviews.r7n": "tuomas.lukee",
    "reviews.r8t": "muut estäjät pystyin ohittamaan 2 napautuksella, käytännössä valehtelin itselleni. tätä et voi kytkeä pois ja kyllä se ärsyttää aluksi mutta on ainoa mikä on koskaan toiminut",
    "reviews.r8n": "kalle_n",
    "reviews.r9t": "tilastot shokeerasivat minut, 6 t 40 min päivässä. alas 3 tuntiin 2 kuukaudessa. sen käyrän laskun seuraaminen on oudosti se motivoivin osa",
    "reviews.r9n": "sanna.k",
    "reviews.r10t": "en päässyt pakoon shorts-mustaa aukkoa joten lukitsin vaan youtuben, ongelma ratkaistu. olisi 5 tähteä widgetillä, muuten ei valittamista",
    "reviews.r10n": "niko_035",
    "reviews.note": "Havainnollistavia esimerkkejä. Tämä osio päivitetään todellisilla App Store -arvosteluilla julkaisun jälkeen.",
    "faq.title": "Usein kysytyt kysymykset",
    "faq.q1": "Enkö todella voi avata lukitusta etuajassa?",
    "faq.a1": "Se on ydinajatus. Kun ajastettu ohjelma alkaa, se pyörii loppuaikaansa asti. Jos voisit kytkeä sen pois kahdella napautuksella, se olisi muistutus, ei lukitus. Aseta kestot harkiten.",
    "faq.q2": "Minne tietoni menevät?",
    "faq.a2": "Ei minnekään. Pawlockilla ei ole tilijärjestelmää eikä palvelimia. Ruutuaikatietosi käsitellään laitteellasi Applen kehyksen kautta, emmekä me näe niitä koskaan.",
    "faq.q3": "Miksi se pyytää ruutuaikaoikeutta?",
    "faq.a3": "Sovellusten lukitseminen onnistuu vain järjestelmän omilla säätimillä: Applen Ruutuaika (Perhejako) iPhonessa ja saavutettavuuspalvelu Androidissa. Lupa annetaan puhelimen järjestelmälle ja se on välttämätön todelliselle estolle.",
    "faq.q4": "Mitä saan ilmaiseksi?",
    "faq.a4": "3 välitöntä lukitusta päivässä, 1 automaattinen ohjelma, sovellusten ja verkkosivustojen estämisen sekä Päivittäiset Ruutuaika-tilastot. Pro avaa rajattomasti ohjelmia ja kaikki nykyiset Pro-ominaisuudet.",
    "faq.q5": "Miten peruutan tilaukseni?",
    "faq.a5": "App Storen tai Google Playn tilauksista, kuten mikä tahansa tilaus. Peruutuksen jälkeen Pro jatkuu maksetun jakson loppuun.",
    "faq.q6": "Mitkä laitteet ovat tuettuja?",
    "faq.a6": "Pawlock toimii iPhonella ja Androidilla. Katso ajantasaiset versiovaatimukset kaupan sivulta.",
    "cta.title": "Ota aikasi takaisin.",
    "cta.sub": "Syötteesi voi odottaa. Elämäsi ei.",
    "cta.button": "Lataa Pawlock",
    "footer.tagline": "Vähemmän ruutua, enemmän elämää.",
    "footer.privacy": "Tietosuojakäytäntö",
    "footer.terms": "Käyttöehdot",
    "footer.contact": "Yhteystiedot",
    "footer.rights": "Kaikki oikeudet pidätetään."
