    "reviews.r2t": "сесія врятувала. заблокувала телефон з 9 до 6 у будні, на перший день паніка, на третій вже звикла. бали на практиці різко пішли вгору",
    "reviews.r2n": "oksana.vchus",
    "reviews.r3t": "я той хлопець, що відкриває інсту на роботі й губить 40 хвилин. робочий розклад тепер весь ранок, телефон практично мертвий до обіду. і ні, шеф мене не змушував, я сам",
