    "reviews.r4t": "спіймав себе на тому, що перевіряю телефон, коли граюся з дитиною, і стало гидко. сімейне блокування з 18 до 21 тепер. донька навіть помітила, що тато більше не дивиться в телефон",
    "reviews.r4n": "taras_tato",
    "reviews.r5t": "видаляла інсту разів 100 і завжди ставила назад. виявляється, видалення не відповідь, блокування, так. 3 тижні чиста, і, чесно, тяга слабшає",
    "reviews.r5n": "iryna.mln",
    "reviews.r6t": "перша година мого дня зникала в телефоні ще до того, як я вставав з ліжка. ранкове блокування з 7 до 9, я п'ю каву й іду на прогулянку. повернути собі цю годину, це інше життя",
    "reviews.r6n": "olena_run",
    "reviews.r7t": "я вже не міг читати книжки, 2 сторінки і рука тягнеться до телефону. вечірнє блокування для читання, і цього місяця я дочитав 3 книги. востаннє таке було в універі",
    "reviews.r7n": "bohdan.chyt",
    "reviews.r8t": "інші блокувальники я обходив у 2 дотики, по суті брехав собі. цей не вимкнеш, і так, спершу це бісить, але це єдине, що взагалі спрацювало",
    "reviews.r8n": "serhiy_k",
    "reviews.r9t": "статистика мене шокувала, 6 год 40 хв на день. за 2 місяці до 3 годин. дивитися, як той графік іде вниз, це, дивно, найбільш мотивуюча частина",
    "reviews.r9n": "mariya.hrb",
    "reviews.r10t": "не міг вибратися з чорної діри shorts, тож просто заблокував youtube, проблему вирішено. було б 5 зірок із віджетом, а так жодних претензій",
    "reviews.r10n": "vitalii_035",
    "reviews.note": "Ілюстративні приклади. Цей розділ буде оновлено реальними відгуками з App Store після запуску.",
    "faq.title": "Часті запитання",
    "faq.q1": "Я справді не можу розблокувати раніше?",
    "faq.a1": "Це і є основна ідея. Щойно запланована програма стартувала, вона працює до свого часу завершення. Якби її можна було вимкнути у два дотики, це було б нагадування, а не блокування. Задавай тривалість обдумано.",
    "faq.q2": "Куди йдуть мої дані?",
    "faq.a2": "Нікуди. У Pawlock немає системи облікових записів і немає серверів. Дані твого Екранного часу обробляються на твоєму пристрої через фреймворк Apple, і ми їх ніколи не бачимо.",
    "faq.q3": "Чому він просить дозвіл до Екранного часу?",
    "faq.a3": "Блокувати застосунки можна лише засобами самої системи: «Екранний час» (Родинний доступ) Apple на iPhone і служба спеціальних можливостей на Android. Дозвіл надається системі телефона й обов'язковий для справжнього блокування.",
    "faq.q4": "Що я отримую безкоштовно?",
    "faq.a4": "3 миттєві блокування на день, 1 автоматична програма, блокування застосунків і вебсайтів та Щоденна статистика Екранного часу. Pro відкриває необмежену кількість програм і усі поточні можливості Pro.",
    "faq.q5": "Як скасувати підписку?",
    "faq.a5": "Через підписки App Store або Google Play, як і будь-яку іншу. Після скасування Pro діє до кінця оплаченого періоду.",
    "faq.q6": "Які пристрої підтримуються?",
    "faq.a6": "Pawlock працює на iPhone і на Android. Актуальні вимоги до версії дивіться на сторінці магазину.",
