    "how.s1d": "Διάλεξε εφαρμογές, ολόκληρες κατηγορίες ή ιστότοπους με τον επίσημο επιλογέα της Apple. Πρόσθεσε οποιονδήποτε ιστότοπο πληκτρολογώντας τη διεύθυνσή του.",
    "how.s2t": "Κλείδωσε τώρα ή με πρόγραμμα",
    "how.s2d": "Ένα άγγιγμα για άμεσο κλείδωμα με χρονόμετρο, ή δημιούργησε αυτόματα προγράμματα: ύπνος, μελέτη, δουλειά. Υποστηρίζονται και ολονύχτια παράθυρα.",
    "how.s3t": "Χωρίς επιστροφή. Αυτό είναι το νόημα.",
    "how.s3d": "Μόλις ξεκινήσει ένα πρόγραμμα, δεν μπορεί να τερματιστεί νωρίτερα. Το Pawlock στέκεται φρουρός για να πας να ζήσεις τη ζωή σου.",
    "features.title": "Όλα όσα χρειάζεσαι για να πάρεις πίσω τον χρόνο σου",
    "features.sub": "Σοβαρό μπλοκάρισμα από κάτω, φιλικό πρόσωπο από πάνω.",
    "features.f1t": "Άμεσο κλείδωμα",
    "features.f1d": "Ένα άγγιγμα κλειδώνει τις επιλεγμένες εφαρμογές και ιστότοπους σου. Γύρνα τον τροχό για να ορίσεις μέρες, ώρες, λεπτά, και δες την αντίστροφη μέτρηση συγκέντρωσης.",
    "features.f2t": "Εξατομικευμένες προτάσεις προγραμμάτων",
    "features.f2d": "Απάντησε σε μερικές ερωτήσεις κατά την εισαγωγή και το Pawlock θα δημιουργήσει αυτόματα μια πρόταση προγράμματος βάσει των συνηθειών, των στόχων και της καθημερινής σου ρουτίνας.",
    "features.f3t": "Αυστηρό εκ σχεδιασμού",
    "features.f3d": "Ένα πρόγραμμα που ξεκίνησε δεν μπορεί να απενεργοποιηθεί νωρίτερα. Το κλείδωμα που δεν πείθεται να αφήσει τη δουλειά του είναι αυτό που αλλάζει τις συνήθειές σου.",
    "features.f4t": "Πραγματικά στατιστικά",
    "features.f4d": "Ημερήσια, εβδομαδιαία και μηνιαία χρήση από τα δεδομένα Χρόνου Οθόνης της Apple. Πραγματικοί αριθμοί από τη συσκευή σου, όχι εκτιμήσεις.",
    "features.f5t": "Και ιστότοποι",
    "features.f5d": "Ο περισπασμός δεν είναι μόνο οι εφαρμογές. Μπλόκαρε ιστότοπους και ολόκληρες κατηγορίες μαζί τους, στο ίδιο κλείδωμα.",
    "features.f6t": "Ιδιωτικό εξ ορισμού",
    "features.f6d": "Χωρίς λογαριασμό, χωρίς διακομιστή, χωρίς διαφημίσεις. Τα δεδομένα Χρόνου Οθόνης σου μένουν στο iPhone σου, εκεί που τα κρατά η Apple.",
    "features.f7t": "Ζωντανή αντίστροφη μέτρηση",
    "features.f7d": "Παρακολούθησε κάθε κλείδωμα με ένα Live Activity με τη μασκότ στην οθόνη κλειδώματος και μια συμπαγή αντίστροφη μέτρηση στο Dynamic Island.",
    "features.f8t": "Έξυπνες καθημερινές ειδοποιήσεις",
    "features.f8d": "Λάβε καθημερινά μια χρήσιμη υπενθύμιση βάσει του σερί, των αποκλεισμένων προσπαθειών ή της εβδομαδιαίας σύνοψης συγκέντρωσης.",
    "spot.auto.badge": "Αυτόματο",
