    "spot.auto.sub": "Όρισε τα προγράμματά σου μία φορά και το Pawlock αναλαμβάνει. Κάθε βράδυ και κάθε πρωί κλειδώνει ακριβώς στην ώρα του. Δεν χρειάζεται καν να το θυμάσαι.",
