    "reviews.sub": "Αληθινές ιστορίες από τη μάχη ενάντια στο scroll.",
    "reviews.r1t": "εκανα scroll μεχρι τις 2 τη νυχτα καθε βραδυ. εβαλα προγραμμα υπνου που κλειδωνει τα παντα στις 11 και η πρωτη εβδομαδα ηταν δυσκολη αλλα τωρα κοιμαμαι κανονικα 7 ωρες",
    "reviews.r1n": "Γιώργος Π.",
    "reviews.r2t": "με εσωσε στην εξεταστικη. κλειδωνα το κινητο 9 με 6 τις καθημερινες, πανικοβληθηκα την πρωτη μερα, το συνηθισα απο την τριτη. οι βαθμοι μου ανεβηκαν κατακορυφα",
    "reviews.r2n": "Ελένη Μ.",
    "reviews.r3t": "ειμαι αυτος που ανοιγει το instagram στη δουλεια και χανει 40 λεπτα. τωρα το προγραμμα εργασιας τρεχει ολο το πρωι, το κινητο ειναι πρακτικα νεκρο μεχρι το μεσημερι. δεν μου το επεβαλε το αφεντικο, το εκανα μονος μου",
    "reviews.r3n": "Δημήτρης Κ.",
    "reviews.r4t": "με επιασα να κοιταζω το κινητο ενω επαιζα με το παιδι μου και ενιωσα χαλια. τωρα εχω οικογενειακο κλειδωμα 6 με 9 το βραδυ. η κορη μου το προσεξε πραγματικα οτι ο μπαμπας δεν κοιταει πια το κινητο",
    "reviews.r4n": "Νίκος Α.",
    "reviews.r5t": "εσβησα το instagram κανα 100 φορες και παντα το ξαναεβαζα. τελικα η διαγραφη δεν ειναι η λυση, το κλειδωμα ειναι. 3 εβδομαδες καθαρος και ειλικρινα η επιθυμια σβηνει",
    "reviews.r5n": "Μαρία Τ.",
    "reviews.r6t": "η πρωτη ωρα της μερας μου χανοταν στο κινητο πριν καν σηκωθω απο το κρεβατι. πρωινο κλειδωμα 7 με 9, πινω τον καφε μου και παω για περπατημα. το να ξανακερδισω εκεινη την ωρα ειναι αλλη ζωη",
    "reviews.r6n": "Κατερίνα Β.",
    "reviews.r7t": "δεν μπορουσα πια να διαβασω βιβλια, 2 σελιδες και το χερι μου πηγαινε στο κινητο. βραδινο κλειδωμα για διαβασμα και τελειωσα 3 βιβλια αυτον τον μηνα. τελευταια φορα που ειχε συμβει ημουν φοιτητης",
    "reviews.r7n": "Θανάσης Ρ.",
    "reviews.r8t": "τα αλλα blockers τα παρακαμπτα με 2 αγγιγματα, ουσιαστικα ελεγα ψεματα στον εαυτο μου. αυτο δεν το κλεινεις και ναι στην αρχη ειναι εκνευριστικο αλλα ειναι το μονο που δουλεψε ποτε",
    "reviews.r8n": "Χρήστος Β.",
    "reviews.r9t": "τα στατιστικα με σοκαραν, 6ω 40λ τη μερα. επεσα στις 3 ωρες σε 2 μηνες. το να βλεπω εκεινο το γραφημα να κατεβαινει ειναι περιεργα το πιο κινητοποιητικο κομματι",
    "reviews.r9n": "Ραφαέλα Κ.",
    "reviews.r10t": "δεν μπορουσα να ξεφυγω απο τη μαυρη τρυπα των shorts οποτε απλα κλειδωσα το youtube, το προβλημα λυθηκε. θα ηταν 5 αστερια με ενα widget, αλλιως κανενα παραπονο",
    "reviews.r10n": "Παναγιώτης Σ.",
    "reviews.note": "Ενδεικτικά παραδείγματα. Αυτή η ενότητα θα ενημερωθεί με πραγματικές κριτικές από το App Store μετά την κυκλοφορία.",
    "faq.title": "Συχνές ερωτήσεις",
    "faq.q1": "Δεν μπορώ πραγματικά να ξεκλειδώσω νωρίτερα;",
    "faq.a1": "Αυτή είναι η βασική ιδέα. Μόλις ξεκινήσει ένα προγραμματισμένο πρόγραμμα, τρέχει μέχρι την ώρα λήξης του. Αν μπορούσες να το κλείσεις με δύο αγγίγματα, θα ήταν υπενθύμιση, όχι κλείδωμα. Όρισε τις διάρκειές σου με σκέψη.",
    "faq.q2": "Πού πηγαίνουν τα δεδομένα μου;",
    "faq.a2": "Πουθενά. Το Pawlock δεν έχει σύστημα λογαριασμών ούτε διακομιστές. Τα δεδομένα Χρόνου Οθόνης σου επεξεργάζονται στη συσκευή σου μέσω του framework της Apple, και δεν τα βλέπουμε ποτέ.",
    "faq.q3": "Γιατί ζητά άδεια για τον Χρόνο Οθόνης;",
    "faq.a3": "Το κλείδωμα εφαρμογών γίνεται μόνο μέσω των εργαλείων του συστήματος: Χρόνος επί οθόνης (Οικογενειακός διαμοιρασμός) της Apple στο iPhone και η υπηρεσία προσβασιμότητας στο Android. Η άδεια δίνεται στο σύστημα του τηλεφώνου και είναι απαραίτητη για πραγματική φραγή.",
    "faq.q4": "Τι παίρνω δωρεάν;",
    "faq.a4": "3 άμεσα κλειδώματα την ημέρα, 1 αυτόματο πρόγραμμα, μπλοκάρισμα εφαρμογών και ιστότοπων, και Ημερήσια στατιστικά Χρόνου Οθόνης. Το Pro ξεκλειδώνει απεριόριστα προγράμματα και όλες τις τρέχουσες λειτουργίες Pro.",
    "faq.q5": "Πώς ακυρώνω τη συνδρομή μου;",
    "faq.a5": "Από τις συνδρομές σας στο App Store ή στο Google Play, όπως κάθε άλλη. Αν ακυρώσετε, το Pro μένει ενεργό ως το τέλος της πληρωμένης περιόδου.",
    "faq.q6": "Ποιες συσκευές υποστηρίζονται;",
    "faq.a6": "Το Pawlock λειτουργεί σε iPhone και Android. Δείτε τη σελίδα του store για τις τρέχουσες απαιτήσεις έκδοσης.",
    "cta.title": "Πάρε πίσω τον χρόνο σου.",
