    "spot.strict.sub": "Většina blokovačů povolí ve chvíli, kdy se opravdu chceš dostat dovnitř. Pawlock ne. Jakmile program začne, není žádný předčasný odchod, žádný únik na dvě klepnutí. To je celý důvod, proč mění tvé návyky.",
