    "reviews.title": "Co lidé říkají",
    "reviews.sub": "Skutečné příběhy z boje proti scrollování.",
    "reviews.r1t": "scrolloval jsem každou noc do dvou do rána. nastavil jsem rozvrh na spánek, co všechno zamkne v 11 a první týden byl drsný, ale teď fakt spím 7 hodin",
    "reviews.r1n": "Jakub Novák",
    "reviews.r2t": "zkouškové mi zachránilo. zamkl jsem telefon od 9 do 18 ve všední dny, první den panika, třetí den už zvyk. moje známky šly hodně nahoru",
    "reviews.r2n": "Tereza Svobodová",
    "reviews.r3t": "jsem ten typ, co si v práci otevře instagram a ztratí 40 minut. pracovní rozvrh teď běží celé dopoledne, telefon je do oběda prakticky mrtvý. šéf mě k tomu nenutil, udělal jsem to sám",
    "reviews.r3n": "Petr Dvořák",
    "reviews.r4t": "přistihl jsem se, jak koukám do telefonu, když si hraju s dcerou, a bylo mi hrozně. teď mám rodinný zámek od 18 do 21. dcera si fakt všimla, že se táta už nedívá do telefonu",
    "reviews.r4n": "Michal Černý",
    "reviews.r5t": "smazal jsem instagram snad stokrát a vždycky ho nainstaloval zpátky. ukázalo se, že mazání není odpověď, zamykání jo. 3 týdny čistý a nutkání fakt slábne",
    "reviews.r5n": "Lucie Procházková",
    "reviews.r6t": "první hodina dne mi mizela do telefonu ještě než jsem vylezl z postele. ranní zámek od 7 do 9, dám si kávu a jdu na procházku. mít tu hodinu zpátky je úplně jiný život",
    "reviews.r6n": "Anna Marková",
    "reviews.r7t": "už jsem nedokázal číst knihy, 2 stránky a ruka sahala po telefonu. večerní zámek na čtení a tenhle měsíc jsem dočetl 3 knihy. naposledy se mi to povedlo na vejšce",
    "reviews.r7n": "Tomáš Veselý",
    "reviews.r8t": "jiné blokovače jsem obešel na 2 klepnutí, prostě jsem lhal sám sobě. tenhle nevypneš a jo, ze začátku je to otravné, ale je to jediné, co kdy fungovalo",
    "reviews.r8n": "Jan Horák",
    "reviews.r9t": "statistiky mě šokovaly, 6 h 40 m denně. za 2 měsíce dolů na 3 hodiny. sledovat, jak ten graf klesá, je kupodivu ta nejvíc motivující věc",
    "reviews.r9n": "Kateřina Kučerová",
    "reviews.r10t": "nedokázal jsem uniknout černé díře shorts, tak jsem prostě zamkl youtube, problém vyřešen. 5 hvězd by bylo s widgetem, jinak nula stížností",
    "reviews.r10n": "Filip Pospíšil",
    "reviews.note": "Ilustrativní příklady. Tato sekce bude po spuštění aktualizována skutečnými recenzemi z App Store.",
    "faq.title": "Časté dotazy",
    "faq.q1": "Vážně nemůžu odemknout dřív?",
    "faq.a1": "To je základní myšlenka. Jakmile naplánovaný program začne, běží až do svého konce. Kdybys ho mohl vypnout na dvě klepnutí, byla by to připomínka, ne zámek. Nastavuj si délky s rozmyslem.",
    "faq.q2": "Kam jdou má data?",
    "faq.a2": "Nikam. Pawlock nemá žádný systém účtů ani žádné servery. Tvá data z Času u obrazovky se zpracovávají na tvém zařízení přes framework od Applu a my je nikdy nevidíme.",
    "faq.q3": "Proč žádá o oprávnění k Času u obrazovky?",
    "faq.a3": "Zamknout aplikace lze jen přes vlastní nástroje systému: Čas u obrazovky (Rodinné sdílení) od Apple na iPhonu a služba přístupnosti na Androidu. Oprávnění se uděluje systému telefonu a je nutné pro skutečné blokování.",
    "faq.q4": "Co dostanu zdarma?",
    "faq.a4": "3 okamžité zámky denně, 1 automatický program, blokování aplikací a webů a Denní statistiky Času u obrazovky. Pro odemyká neomezený počet programů a všechny aktuální funkce Pro.",
    "faq.q5": "Jak zruším své předplatné?",
    "faq.a5": "Přes předplatné v App Storu nebo Google Play, jako kterékoli jiné. Po zrušení Pro platí do konce zaplaceného období.",
    "faq.q6": "Která zařízení jsou podporována?",
    "faq.a6": "Pawlock běží na iPhonu i na Androidu. Aktuální požadavky na verzi najdete na stránce obchodu.",
    "cta.title": "Vezmi si svůj čas zpátky.",
    "cta.sub": "Tvůj feed počká. Tvůj život ne.",
    "cta.button": "Stáhnout Pawlock",
    "footer.tagline": "Méně obrazovky, více života.",
    "footer.privacy": "Zásady ochrany soukromí",
