    "meta.description": "Pawlock este o aplicație de blocare pentru iPhone și Android care blochează aplicațiile și site-urile care distrag, folosind controalele proprii ale telefonului. Blochează rețelele sociale, creează programe de concentrare și recuperează-ți ziua.",
