    "problem.c2t": "Ștergerea nu funcționează",
    "problem.c2d": "Ștergi aplicația hotărât. Două zile mai târziu e din nou pe ecranul principal.",
    "problem.c3t": "Memento-urile pot fi ignorate",
    "problem.c3d": "Avertizările despre timpul pe ecran și ferestrele „ia o pauză” sunt înlăturate cu o singură atingere. Ai nevoie de o blocare, nu de o sugestie.",
