    "features.f2t": "Sugestii personalizate de programe",
    "features.f2d": "Răspunde la câteva întrebări la început, iar Pawlock va crea automat o sugestie de program în funcție de obiceiurile, obiectivele și rutina ta zilnică.",
    "features.f3t": "Strict prin design",
