    "spot.strict.sub": "Majoritatea blocatoarelor cedează în clipa în care chiar vrei să intri. Pawlock nu. Odată ce un program începe, nu există ieșire mai devreme, nicio scăpare din două atingeri. Ăsta e întregul motiv pentru care îți schimbă obiceiurile.",
