    "problem.title": "Nem te vagy a hibás. Így tervezték.",
    "problem.sub": "Az időrablóid appjait több ezer mérnök építette egyetlen céllal: hogy görgess tovább. Az akaraterő sosem volt tisztességes küzdelem.",
    "problem.c1t": "„Csak öt perc”",
    "problem.c1d": "Egy pillanatra nyitod meg. Egy órával később még mindig ott vagy, és arra sem emlékszel, mit láttál.",
    "problem.c2t": "A törlés nem működik",
