    "problem.c3t": "Az emlékeztetők figyelmen kívül hagyhatók",
    "problem.c3d": "A képernyőidő-figyelmeztetéseket és a „tarts szünetet” felugró ablakokat egyetlen koppintással elhessegeted. Zárolásra van szükséged, nem javaslatra.",
    "problem.stat1n": "4+ óra",
    "problem.stat1d": "ennyit tölt az átlagember a telefonjával minden egyes nap",
