    "problem.stat3n": "4-ből 1",
    "problem.stat3d": "ébren töltött óra a telefoné, egy 16 órás ébren töltött napon",
    "problem.note": "A számítás egyszerű: 4 óra × 365 nap = évi 1460 óra. Számíts egy napot 16 ébren töltött órával (a másik 8 az alvás), és ez 91 teljes ébren töltött nap. A Pawlock statisztikái a saját számodat mutatják, egyenesen a készülékedről.",
    "transition.title": "A másik oldalon az életed vár rád.",
    "transition.sub": "Semmit sem veszítesz azzal, ha leteszed a telefont. Egy egész napot nyersz vissza.",
    "how.title": "Hogyan működik a Pawlock",
    "how.sub": "Három lépés. Utána a rendszer akkor is működik, amikor a motivációd nem.",
    "how.s1t": "Válaszd ki, mi vonja el a figyelmed",
    "how.s1d": "Válassz appokat, egész kategóriákat vagy webhelyeket az Apple hivatalos választójával. Bármely webhelyet hozzáadhatsz a címe beírásával.",
    "how.s2t": "Zárolj most, vagy ütemezve",
