    "features.title": "Minden, amivel visszaveheted az időd",
    "features.sub": "Komoly zárolás alul, barátságos arc felül.",
    "features.f1t": "Azonnali zárolás",
    "features.f1d": "Egy koppintás zárolja a kiválasztott appjaidat és webhelyeidet. Pörgesd a kereket a napok, órák és percek beállításához, és nézd a fókusz-visszaszámlálót.",
    "features.f2t": "Személyre szabott programjavaslatok",
