    "features.f6t": "Alapból privát",
    "features.f6d": "Nincs fiók, nincs szerver, nincs reklám. A Képernyőidő-adataid az iPhone-odon maradnak, ahol az Apple tartja őket.",
    "features.f7t": "Élő visszaszámlálás",
    "features.f7d": "Kövesd minden zárolás állapotát a zárolási képernyőn megjelenő, kabalás Live Activityvel és a Dynamic Island kompakt visszaszámlálójával.",
    "features.f8t": "Okos napi értesítések",
    "features.f8d": "Kapj naponta hasznos értesítést a sorozatod, a blokkolt próbálkozások vagy a heti fókuszösszesítő alapján.",
    "spot.auto.badge": "Automatikus",
    "spot.auto.title": "Résen van, még alvás közben is.",
    "spot.auto.sub": "Állítsd be egyszer a programjaidat, és a Pawlock átveszi az irányítást. Minden este és minden reggel pontosan időben zárol. Még emlékezned sem kell rá.",
    "spot.auto.b1": "Éjszakán átnyúló időablakok, például 23:00 → 7:00",
