    "reviews.r1t": "minden áldott éjjel hajnali 2-ig görgettem. beállítottam egy alvásütemezést, ami 23-kor mindent bezár, az első hét kemény volt, de most tényleg alszom 7 órát",
    "reviews.r1n": "Bence.M",
    "reviews.r2t": "a vizsgaidőszakban mentett meg. hétköznap 9-től 18-ig zároltam a telefonom, az első nap pánikoltam, harmadikra megszoktam. sokkal jobbak lettek a jegyeim",
    "reviews.r2n": "eszter.tanul",
    "reviews.r3t": "én vagyok az a pasi, aki munka közben megnyitja az instagramot és elveszít 40 percet. a munkaütemezés most egész délelőtt fut, a telefon gyakorlatilag halott ebédig. és nem a főnököm kényszerített rá, én akartam",
    "reviews.r3n": "daniel_kod",
    "reviews.r4t": "azon kaptam magam, hogy a gyerekemmel játszva a telefonom nézem, és szörnyen éreztem magam. most családi zárolás este 6-tól 9-ig. a lányom tényleg észrevette, hogy apa már nem néz a telefonjára",
    "reviews.r4n": "mate_apa",
    "reviews.r5t": "vagy 100-szor töröltem az instagramot és mindig visszatettem. kiderült, hogy nem a törlés a megoldás, hanem a zárolás. 3 hete tiszta vagyok és őszintén az inger egyre halkul",
    "reviews.r5n": "anna.kovacs",
    "reviews.r6t": "a napom első órája régen elment a telefonomon, mielőtt még kikeltem volna az ágyból. reggeli zárolás 7-től 9-ig, megiszom a kávém és sétálni megyek. azt az órát visszaszerezni egy másik élet",
    "reviews.r6n": "reka_fut",
    "reviews.r7t": "már nem tudtam könyvet olvasni, 2 oldal és a kezem a telefon után nyúlt. esti olvasászárolás és ebben a hónapban 3 könyvet fejeztem be. legutóbb az egyetemen történt ilyen",
    "reviews.r7n": "tamas.olvas",
    "reviews.r8t": "más blokkolókat 2 koppintással megkerültem, gyakorlatilag hazudtam magamnak. ezt nem tudod kikapcsolni és igen elsőre idegesítő, de ez az egyetlen, ami valaha bevált",
    "reviews.r8n": "gabor_b",
    "reviews.r9t": "a statisztika sokkolt, napi 6 óra 40 perc. 2 hónap alatt lementem 3 órára. azt a grafikont lefelé menni nézni fura módon a legmotiválóbb rész",
    "reviews.r9n": "orsolya.k",
    "reviews.r10t": "nem tudtam kimászni a shorts fekete lyukból, úgyhogy simán bezártam a youtube-ot, megoldva. widgettel 5 csillag lenne, egyébként semmi panasz",
    "reviews.r10n": "levente_035",
    "reviews.note": "Szemléltető példák. Ezt a részt indulás után valódi App Store-értékelésekkel frissítjük.",
    "faq.title": "Gyakran ismételt kérdések",
    "faq.q1": "Tényleg nem tudom korábban feloldani?",
    "faq.a1": "Ez a lényeg. Ha egy ütemezett program elindul, a záró időpontjáig fut. Ha két koppintással ki tudnád kapcsolni, az emlékeztető lenne, nem zárolás. Az időtartamokat átgondoltan állítsd be.",
    "faq.q2": "Hová kerülnek az adataim?",
    "faq.a2": "Sehová. A Pawlocknak nincs fiókrendszere és nincsenek szerverei. A Képernyőidő-adataid a készülékeden dolgozódnak fel az Apple keretrendszerén keresztül, és mi sosem látjuk őket.",
    "faq.q3": "Miért kér Képernyőidő-engedélyt?",
    "faq.a3": "Alkalmazásokat zárolni csak a rendszer saját vezérlőivel lehet: az Apple Képernyőidő (Családi megosztás) iPhone-on, és a kisegítő szolgáltatás Androidon. Az engedélyt a telefon rendszere kapja, és valódi tiltáshoz elengedhetetlen.",
    "faq.q4": "Mit kapok ingyen?",
    "faq.a4": "Napi 3 azonnali zárolás, 1 automatikus program, app- és webhelyblokkolás, valamint Napi Képernyőidő-statisztikák. A Pro korlátlan programot old fel, és minden jelenlegi Pro funkciót tartalmaz.",
    "faq.q5": "Hogyan mondom le az előfizetésem?",
    "faq.a5": "Az App Store vagy a Google Play előfizetéseidből, mint bármelyik másik. Lemondás után a Pro a kifizetett időszak végéig marad.",
    "faq.q6": "Mely eszközök támogatottak?",
    "faq.a6": "A Pawlock iPhone-on és Androidon is fut. Az aktuális verziókövetelmények a bolti oldalon találhatók.",
    "cta.title": "Vedd vissza az időd.",
    "cta.sub": "A hírfolyamod várhat. Az életed nem.",
