    "spot.strict.sub": "Väčšina blokovačov povolí v momente, keď sa naozaj chceš dostať dnu. Pawlock nie. Keď sa program spustí, niet predčasného východu, niet úniku na dve klepnutia. To je celý dôvod, prečo mení tvoje návyky.",
    "spot.strict.b1": "Spustené programy nemožno predčasne ukončiť",
