    "reviews.title": "Čo ľudia hovoria",
    "reviews.sub": "Skutočné príbehy z boja proti scrollovaniu.",
    "reviews.r1t": "scrolloval som každú noc do druhej rána. nastavil som si rozvrh spánku, ktorý o jedenástej všetko uzamkne, prvý týždeň bol drsný ale teraz naozaj spím 7 hodín",
    "reviews.r1n": "Martin K.",
    "reviews.r2t": "skúškové ma zachránilo. uzamkol som telefón od 9 do 6 cez pracovné dni, prvý deň panika, na tretí deň som si zvykol. moje výsledky išli výrazne hore",
    "reviews.r2n": "Zuzana H.",
    "reviews.r3t": "som ten typ čo otvorí instagram v práci a stratí 40 minút. pracovný rozvrh mi teraz beží celé dopoludnie, telefón je v podstate mŕtvy až do obeda. šéf ma k tomu nenútil mimochodom, urobil som to sám",
    "reviews.r3n": "Peter B.",
    "reviews.r4t": "pristihol som sa ako pozerám na telefón keď sa hrám s dieťaťom a bolo mi hrozne. teraz rodinný zámok od 6 do 9 večer. dcéra si naozaj všimla že ocko sa už nepozerá do telefónu",
    "reviews.r4n": "Michal T.",
    "reviews.r5t": "zmazal som instagram asi stokrát a vždy ho nainštaloval späť. ukázalo sa že mazanie nie je odpoveď, uzamknutie áno. 3 týždne čistý a chuť úprimne mizne",
    "reviews.r5n": "Katarína M.",
    "reviews.r6t": "prvá hodina môjho dňa mi mizla v telefóne ešte než som vstal z postele. ranný zámok od 7 do 9, vypijem si kávu a idem na prechádzku. mať tú hodinu späť je iný život",
    "reviews.r6n": "Lucia R.",
    "reviews.r7t": "už som nevedel čítať knihy, 2 strany a ruka siahala po telefóne. večerný zámok na čítanie a tento mesiac som dočítal 3 knihy. naposledy sa to stalo na výške",
    "reviews.r7n": "Tomáš V.",
    "reviews.r8t": "iné blokovače som obišiel na 2 klepnutia, v podstate som klamal sám seba. tento nevypneš a áno spočiatku to je otravné ale je to jediné čo kedy zabralo",
    "reviews.r8n": "Jozef S.",
    "reviews.r9t": "štatistiky ma šokovali, 6h 40m denne. za 2 mesiace dole na 3 hodiny. sledovať ako ten graf klesá je čudne tá najmotivujúcejšia časť",
    "reviews.r9n": "Simona K.",
    "reviews.r10t": "nevedel som uniknúť z čiernej diery shorts tak som proste uzamkol youtube, problém vyriešený. bolo by to na 5 hviezd s widgetom, inak žiadne výhrady",
    "reviews.r10n": "Marek D.",
    "reviews.note": "Ilustračné príklady. Táto sekcia bude po spustení aktualizovaná skutočnými recenziami z App Store.",
    "faq.title": "Časté otázky",
    "faq.q1": "Naozaj sa nedá odomknúť predčasne?",
    "faq.a1": "To je základná myšlienka. Keď sa naplánovaný program spustí, beží až do svojho času konca. Keby si ho vypol na dve klepnutia, bola by to pripomienka, nie zámok. Nastav svoje trvania premyslene.",
    "faq.q2": "Kam idú moje údaje?",
    "faq.a2": "Nikam. Pawlock nemá žiadny systém účtov ani servery. Tvoje údaje z Času pred obrazovkou sa spracúvajú na tvojom zariadení cez framework od Apple a my ich nikdy nevidíme.",
    "faq.q3": "Prečo žiada povolenie k Času pred obrazovkou?",
    "faq.a3": "Zamknúť aplikácie sa dá len cez vlastné nástroje systému: Čas pri obrazovke (Rodinné zdieľanie) od Apple na iPhone a služba prístupnosti na Androide. Povolenie sa udeľuje systému telefónu a je nutné pre skutočné blokovanie.",
    "faq.q4": "Čo dostanem zadarmo?",
    "faq.a4": "3 okamžité zámky denne, 1 automatický program, blokovanie aplikácií a webových stránok a Denné štatistiky Času pred obrazovkou. Pro odomyká neobmedzený počet programov a všetky aktuálne Pro funkcie.",
    "faq.q5": "Ako zruším predplatné?",
    "faq.a5": "Cez predplatné v App Store alebo Google Play, ako každé iné. Po zrušení Pro platí do konca zaplateného obdobia.",
    "faq.q6": "Ktoré zariadenia sú podporované?",
    "faq.a6": "Pawlock beží na iPhone aj na Androide. Aktuálne požiadavky nájdete na stránke obchodu.",
    "cta.title": "Vezmi si svoj čas späť.",
    "cta.sub": "Tvoj feed počká. Tvoj život nie.",
    "cta.button": "Stiahnuť Pawlock",
