    "hero.trust3": "Изградено върху собствените системни контроли на телефона ви",
    "hero.trust4": "Без реклами",
    "problem.title": "Не си ти. Дизайнът е.",
    "problem.sub": "Приложенията, които крадат времето ти, са създадени от хиляди инженери с една цел: да те задържат да скролваш. Волята никога не е била равностоен противник.",
    "problem.c1t": "„Само пет минути“",
    "problem.c1d": "Отваряш го за миг. Час по-късно още си там и дори не помниш какво си видял.",
    "problem.c2t": "Изтриването не работи",
    "problem.c2d": "Изтриваш приложението с решителност. Два дни по-късно то отново е на началния ти екран.",
    "problem.c3t": "Напомнянията се пренебрегват",
    "problem.c3d": "Предупрежденията за екранно време и изскачащите съобщения „почини си“ се отхвърлят с едно докосване. Нужно ти е заключване, а не предложение.",
    "problem.stat1n": "4+ часа",
    "problem.stat1d": "прекарва средният човек на телефона си всеки един ден",
    "problem.stat2n": "91 дни",
