    "problem.stat3n": "1 на 4",
    "problem.stat3d": "будни часа отиват за телефона, при 16-часов буден ден",
    "problem.note": "Сметката е проста: 4 часа × 365 дни = 1460 часа на година. Приемем ли деня за 16 будни часа (другите 8 са сън), това са 91 пълни будни дни. Статистиката на Pawlock показва твоето собствено число, направо от устройството ти.",
    "transition.title": "От другата страна животът ти те чака.",
    "transition.sub": "Не губиш нищо, като оставиш телефона. Печелиш обратно цял ден.",
