    "features.f8t": "Интелигентни ежедневни известия",
    "features.f8d": "Получавайте полезно ежедневно напомняне според серията, блокираните опити или седмичното обобщение на фокуса.",
    "spot.auto.badge": "Автоматично",
    "spot.auto.title": "На пост, дори докато спиш.",
    "spot.auto.sub": "Задай програмите си веднъж и Pawlock поема. Всяка вечер и всяка сутрин заключва точно навреме. Дори не се налага да помниш.",
    "spot.auto.b1": "Нощни прозорци, като 23:00 → 7:00",
    "spot.auto.b2": "Известие, когато всяка програма започне",
    "spot.auto.b3": "Всеки ден, делнични дни или уикенди с едно докосване",
