    "spot.strict.title": "Заключване, от което не можеш да се измъкнеш с приказки.",
    "spot.strict.sub": "Повечето блокиращи приложения се предават в момента, в който наистина поискаш да влезеш. Pawlock не се предава. Щом програмата започне, няма ранен изход, няма измъкване с две докосвания. Точно затова променя навиците ти.",
    "spot.strict.b1": "Започнали програми не могат да бъдат прекратени рано",
    "spot.strict.b2": "Изградено върху системното Screen Time на Apple",
