    "reviews.title": "Какво казват хората",
    "reviews.sub": "Истински истории от битката срещу скролването.",
    "reviews.r1t": "скролвах до 2 през нощта всяка вечер. зададох график за сън, който заключва всичко в 23 и първата седмица беше тежко, но сега наистина спя по 7 часа",
    "reviews.r1n": "georgi_mk",
    "reviews.r2t": "сесията ме спаси. заключих телефона си от 9 до 18 в делничните дни, паникьосах се на първия ден, свикнах на третия. резултатите ми от подготовката се вдигнаха много",
    "reviews.r2n": "mariya.uchi",
    "reviews.r3t": "аз съм тоя, дето отваря инстаграм на работа и губи 40 минути. работният график върви цяла сутрин сега, телефонът е практически мъртъв до обяд. шефът не ме накара между другото, аз си го направих",
    "reviews.r3n": "ivan_code",
    "reviews.r4t": "хванах се да гледам телефона, докато си играех с детето, и се почувствах ужасно. семейно заключване от 18 до 21 сега. дъщеря ми наистина забеляза, че тати вече не гледа телефона си",
    "reviews.r4n": "mihail_tati",
    "reviews.r5t": "изтривах инстаграм към 100 пъти и винаги го инсталирах пак. оказва се, че изтриването не е отговорът, заключването е. 3 седмици чист и честно, желанието избледнява",
    "reviews.r5n": "yana.mileva",
    "reviews.r6t": "първият час от деня ми изчезваше в телефона, преди дори да стана от леглото. сутрешно заключване от 7 до 9, пия си кафето и излизам на разходка. да си върна този час е съвсем друг живот",
    "reviews.r6n": "elena_run",
    "reviews.r7t": "вече не можех да чета книги, 2 страници и ръката ми посягаше към телефона. вечерно заключване за четене и завърших 3 книги този месец. последно това ми се случи в университета",
    "reviews.r7n": "todor.chete",
    "reviews.r8t": "други блокиращи можех да заобиколя с 2 докосвания, все едно се лъжа сам. това не можеш да го изключиш и да, дразнещо е в началото, но е единственото, което някога проработи",
    "reviews.r8n": "hristo_b",
    "reviews.r9t": "статистиката ме шокира, 6ч 40м на ден. паднах до 3 часа за 2 месеца. да гледам как тази графика слиза е странно най-мотивиращата част",
    "reviews.r9n": "ralitsa.k",
    "reviews.r10t": "не можех да избягам от черната дупка на шортс, така че просто заключих ютюб, проблемът решен. щеше да е 5 звезди с джаджа за началния екран, иначе нула оплаквания",
    "reviews.r10n": "kaloyan_035",
    "reviews.note": "Илюстративни примери. Този раздел ще бъде обновен с истински отзиви от App Store след пускането.",
    "faq.title": "Често задавани въпроси",
    "faq.q1": "Наистина ли не мога да отключа рано?",
    "faq.a1": "Това е основната идея. Щом планирана програма започне, тя върви до крайния си час. Ако можеше да я изключиш с две докосвания, това щеше да е напомняне, а не заключване. Задавай продължителностите обмислено.",
    "faq.q2": "Къде отиват данните ми?",
    "faq.a2": "Никъде. Pawlock няма система за акаунти и няма сървъри. Данните ти от Screen Time се обработват на устройството ти чрез рамката на Apple и ние никога не ги виждаме.",
    "faq.q3": "Защо иска разрешение за Screen Time?",
    "faq.a3": "Заключването на приложения е възможно само чрез собствените контроли на системата: Screen Time (Семейно споделяне) на Apple на iPhone и услугата за достъпност на Android. Разрешението се дава на системата на телефона и е задължително за истинско блокиране.",
    "faq.q4": "Какво получавам безплатно?",
    "faq.a4": "3 мигновени заключвания на ден, 1 автоматична програма, блокиране на приложения и уебсайтове, и Дневна статистика от Screen Time. Pro отключва неограничен брой програми и всички текущи Pro функции.",
    "faq.q5": "Как да откажа абонамента си?",
    "faq.a5": "През абонаментите ви в App Store или Google Play, като всеки друг. При отказ Pro остава до края на платения период.",
    "faq.q6": "Кои устройства се поддържат?",
    "faq.a6": "Pawlock работи на iPhone и на Android. Вижте страницата в магазина за текущите изисквания.",
    "cta.title": "Върни си времето.",
    "cta.sub": "Емисията ти може да почака. Животът ти не може.",
