    "reviews.title": "Što ljudi kažu",
    "reviews.sub": "Prave priče iz borbe protiv skrolanja.",
    "reviews.r1t": "skrolala sam do 2 ujutro svaku noć. postavila sam raspored spavanja koji sve zaključa u 23 i prvi tjedan je bio grozan ali sad zaista spavam 7 sati",
    "reviews.r1n": "ivana_k",
    "reviews.r2t": "ispitni rok me spasio. zaključao telefon od 9 do 18 radnim danima, prvi dan panika, treći dan navikao. rezultati na probnim testovima skočili",
    "reviews.r2n": "marko.uci",
    "reviews.r3t": "ja sam tip koji otvori instagram na poslu i izgubi 40 minuta. radni raspored mi sad traje cijelo jutro, telefon je praktički mrtav do ručka. šef me nije tjerao btw, sam sam odlučio",
    "reviews.r3n": "dario_dev",
    "reviews.r4t": "uhvatila sam se kako gledam u telefon dok se igram s djetetom i bilo mi je grozno. obiteljsko zaključavanje od 18 do 21 sad. moja kćer je stvarno primijetila da mama više ne gleda u telefon",
    "reviews.r4n": "petra_mama",
    "reviews.r5t": "izbrisao instagram valjda 100 puta i uvijek ga ponovno instalirao. ispada da brisanje nije odgovor, zaključavanje je. 3 tjedna čisto i iskreno želja slabi",
    "reviews.r5n": "josip.horvat",
    "reviews.r6t": "prvi sat mog dana nestajao je u telefonu prije nego sam uopće ustao iz kreveta. jutarnje zaključavanje 7 do 9, popijem kavu i odem u šetnju. vratiti si taj sat je drugi život",
    "reviews.r6n": "ana_trci",
    "reviews.r7t": "više nisam mogao čitati knjige, 2 stranice i ruka bi mi posegnula za telefonom. večernje zaključavanje za čitanje i pročitao sam 3 knjige ovaj mjesec. zadnji put se to dogodilo na faksu",
    "reviews.r7n": "tomislav.cita",
    "reviews.r8t": "druge blokatore sam mogao zaobići u 2 dodira, u biti sam lagao sam sebi. ovaj ne možeš isključiti i da, iritantno je na početku ali je jedino što je ikad upalilo",
    "reviews.r8n": "kristijan_b",
    "reviews.r9t": "statistika me šokirala, 6h 40m dnevno. pala na 3 sata za 2 mjeseca. gledati kako taj grafikon pada je začudo najmotivirajući dio",
    "reviews.r9n": "maja.k",
    "reviews.r10t": "nisam mogao pobjeći iz crne rupe shortsa pa sam samo zaključao youtube, problem riješen. bilo bi 5 zvjezdica s widgetom, inače nemam nikakvih primjedbi",
    "reviews.r10n": "luka_035",
    "reviews.note": "Ilustrativni primjeri. Ovaj odjeljak bit će ažuriran stvarnim recenzijama s App Storea nakon lansiranja.",
    "faq.title": "Često postavljana pitanja",
    "faq.q1": "Zaista ne mogu otključati ranije?",
    "faq.a1": "To je temeljna ideja. Kad zakazani program jednom započne, traje do svog vremena završetka. Kad bi ga mogao isključiti u dva dodira, bio bi podsjetnik, a ne zaključavanje. Pažljivo postavi trajanja.",
    "faq.q2": "Kamo idu moji podaci?",
    "faq.a2": "Nikamo. Pawlock nema sustav računa ni servere. Tvoji podaci Vremena pred ekranom obrađuju se na tvom uređaju putem Appleovog okvira, i mi ih nikada ne vidimo.",
    "faq.q3": "Zašto traži dopuštenje za Vrijeme pred ekranom?",
    "faq.a3": "Zaključavanje aplikacija moguće je samo preko vlastitih kontrola sustava: Appleov Screen Time (Obiteljsko dijeljenje) na iPhoneu i usluga pristupačnosti na Androidu. Dopuštenje se daje sustavu telefona i nužno je za stvarno blokiranje.",
    "faq.q4": "Što dobivam besplatno?",
